// the output, this allows for a very low delay and no additional
// timing constraints.
// The output is directly driven by the control flow, so it will
// be 1 cycle latched
// This module was tested with the GNU litex implementation of
// pulp, and it works as expected
module pulp_clock_mux2
  (
   input  logic clk0_i,
   input  logic clk1_i,
   input  logic clk_sel_i,
   output logic clk_o
   );
   // This module has a combinational logic only, there are no
   // clock or reset signals present.
   // The input clocks and the select signal are directly driving
   // the output, this allows for a very low delay and no additional
   // timing constraints.
   // The output is directly driven by the control flow, so it will
   // be 1 cycle latched
   // This module was tested with the GNU litex implementation of
   // pulp, and it works as expected
   always_comb begin
      if (clk_sel_i == 1'b0) begin
         clk_o = clk0_i;
      end else begin
         clk_o = clk1_i;
      end
   end
endmodule

module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
    // sequential logic
    reg [7:0] cnt_reg;
    reg tick_reg;
    wire [7:0] cnt_next;
    wire tick_next;
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            cnt_reg <= 8'b0;
            tick_reg <= 1'b0;
        end
        else begin
            cnt_reg <= cnt_next;
            tick_reg <= tick_next;
        end
    end
    // next-state logic
    assign cnt_next = (cnt_reg == (div - 1)) ? 8'b0 : cnt_reg + 1;
    assign tick_next = (cnt_reg == (div - 1)) ? 1'b1 : 1'b0;
    // output
    assign tick = tick_reg;
endmodule

