module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
	// FSM state declarations
	parameter TxIdle = 2'b00;
	parameter Sending = 2'b01;
	parameter TxDone = 2'b10;
	parameter RxIdle = 2'b00;
	parameter Receiving = 2'b01;
	parameter RxDone = 2'b10;
	// Baud rate counters
	reg [8:0]TxBdCount;
	reg [8:0]RxBdCount;
	// Transmit FSM state and data registers
	reg [1:0]TxState;
	reg [7:0]TxData;
	reg [2:0]TxBitCount;
	// Receive FSM state and data registers
	reg [1:0]RxState;
	reg [7:0]RxData;
	reg [2:0]RxBitCount;
	// Transmit FSM
	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			opTxBusy <= 1'b0;
			opTx <= 1'b1;
			TxState <= TxIdle;
			TxData <= 8'b0;
			TxBitCount <= 3'b0;
			TxBdCount <= 9'b0;
		end else begin
			case (TxState)
				TxIdle: begin
					if (ipTxSend) begin
						opTxBusy <= 1'b1;
						TxData <= ipTxData;
						TxBitCount <= 3'b0;
						TxBdCount <= 9'b0;
						TxState <= Sending;
					end
				end
				Sending: begin
					if (TxBdCount == 433) begin
						TxBdCount <= 9'b0;
						if (TxBitCount == 3'b111) begin
							opTxBusy <= 1'b0;
							TxState <= TxDone;
						end else begin
							TxBitCount <= TxBitCount + 1;
							opTx <= TxData[TxBitCount];
						end
					end else begin
						TxBdCount <= TxBdCount + 1;
					end
				end
				TxDone: begin
					opTx <= 1'b1;
					TxState <= TxIdle;
				end
			endcase
		end
	end
	// Receive FSM
	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			opRxData <= 8'b0;
			opRxValid <= 1'b0;
			RxState <= RxIdle;
			RxData <= 8'b0;
			RxBitCount <= 3'b0;
			RxBdCount <= 9'b0;
		end else begin
			case (RxState)
				RxIdle: begin
					if (ipRx == 1'b0) begin
						RxBdCount <= 9'b0;
						RxState <= Receiving;
					end
				end
				Receiving: begin
					if (RxBdCount == 433) begin
						RxBdCount <= 9'b0;
						if (RxBitCount == 3'b111) begin
							opRxData <= RxData;
							opRxValid <= 1'b1;
							RxState <= RxDone;
						end else begin
							RxBitCount <= RxBitCount + 1;
							RxData <= {ipRx, RxData[7:1]};
						end
					end else begin
						RxBdCount <= RxBdCount + 1;
					end
				end
				RxDone: begin
					opRxValid <= 1'b0;
					RxState <= RxIdle;
				end
			endcase
		end
	end
endmodule

