module add_1_bit(
input wire clk,
input wire x,
input wire y,
input wire cin,
output reg sum,
output reg cout
);
reg sum_comb;
reg cout_comb;
always @(posedge clk)
begin
	sum <= sum_comb;
	cout <= cout_comb;
end
always @(*)
begin
	sum_comb = x ^ y ^ cin;
	cout_comb = (x & y) | (y & cin) | (x & cin);
end
endmodule

