module is used for concatenating the x and y address into a single
// 32-bit address bus. This is useful for VGA controllers where the memory
// is accessed in a single, flat address space.
//
// -----------------------------------------------------------------------------
module vga_address_pack(
input wire [9:0] x_addr,
input wire [9:0] y_addr,
output wire [31:0] pack_addr
);
// The address is packed into the top 20 bits of the 32-bit address bus.
// The 12 unused bits are set to zero.
assign pack_addr[11:0] = 12'b0;
assign pack_addr[21:12] = y_addr;
assign pack_addr[31:22] = x_addr;
endmodule

module ALU(A_i, B_i, data_o, ALU_OpCode_i);
	input [15:0] A_i, B_i;
	input [1:0] ALU_OpCode_i;
	output [15:0] data_o;
	reg [15:0] data_o;
	always @(*) begin
		case (ALU_OpCode_i)
			2'b00: data_o = A_i + B_i;
			2'b01: data_o = A_i - B_i;
			2'b10: data_o = A_i & B_i;
			default: data_o = 16'b0; // undefined
		endcase
	end
endmodule

module CAS(
	input [3:0] IN,
	output [3:0] OUT
	);
	assign OUT[0] = (~IN[3] & ~IN[2] & IN[1]) | (~IN[3] & IN[2] & ~IN[1]) | (IN[3] & ~IN[2] & ~IN[1]) | (IN[3] & IN[2] & IN[1]);
	assign OUT[1] = (~IN[3] & ~IN[2] & IN[0]) | (~IN[3] & IN[2] & ~IN[0]) | (IN[3] & ~IN[2] & ~IN[0]) | (IN[3] & IN[2] & IN[0]);
	assign OUT[2] = IN[1];
	assign OUT[3] = IN[0];
endmodule

module uses an array of registers (SRL_SIG) to store the data, which is shifted sequentially under clock control, and provides the selected data at the output (q) based on the current address.
module FIFO_toe_rtTimer2stateTable_releaseStat_shiftReg (
    clk,
    data,
    ce,
    a,
    q);
    parameter DATA_WIDTH = 16;
    parameter ADDR_WIDTH = 2;
    input clk;
    input [DATA_WIDTH - 1:0] data;
    input ce;
    input [ADDR_WIDTH - 1:0] a;
    output [DATA_WIDTH - 1:0] q;
    reg[DATA_WIDTH - 1:0] SRL_SIG[2:0];
    always @ (posedge clk)
    begin
        if (ce)
        begin
            SRL_SIG[2] <= SRL_SIG[1];
            SRL_SIG[1] <= SRL_SIG[0];
            SRL_SIG[0] <= data;
        end
    end
    assign q = SRL_SIG[a];
endmodule

module mode0(
input wire clk_i,
input wire [9:0] pix_x_i,
input wire [9:0] pix_y_i,
output reg [16:0] vram_addr_o,
input wire [7:0] vram_rd_data_i,
output reg [7:0] pal_addr_o,
input wire [11:0] pal_rd_data_i,
