output reg [11:0] col_o,
output reg [9:0] delay_o
);
reg [7:0] tile_n;
reg [7:0] color_n;
reg [7:0] tile_0r, tile_1r, tile_2r, tile_3r, tile_4r;
reg [7:0] color_0r, color_1r, color_2r, color_3r, color_4r;
reg [9:0] pix_x_0r, pix_x_1r, pix_x_2r, pix_x_3r, pix_x_4r;
reg [9:0] pix_y_0r, pix_y_1r, pix_y_2r, pix_y_3r, pix_y_4r;
reg [7:0] vram_rd_data_0r, vram_rd_data_1r, vram_rd_data_2r, vram_rd_data_3r, vram_rd_data_4r;
reg [11:0] pal_rd_data_0r, pal_rd_data_1r, pal_rd_data_2r, pal_rd_data_3r, pal_rd_data_4r;
always @(posedge clk_i) begin
    pix_x_0r <= pix_x_i;
    pix_y_0r <= pix_y_i;
    vram_rd_data_0r <= vram_rd_data_i;
    pal_rd_data_0r <= pal_rd_data_i;
end
always @(posedge clk_i) begin
    pix_x_1r <= pix_x_0r;
    pix_y_1r <= pix_y_0r;
    vram_rd_data_1r <= vram_rd_data_0r;
    pal_rd_data_1r <= pal_rd_data_0r;
end
always @(posedge clk_i) begin
    pix_x_2r <= pix_x_1r;
    pix_y_2r <= pix_y_1r;
    vram_rd_data_2r <= vram_rd_data_1r;
    pal_rd_data_2r <= pal_rd_data_1r;
end
always @(posedge clk_i) begin
    pix_x_3r <= pix_x_2r;
    pix_y_3r <= pix_y_2r;
    vram_rd_data_3r <= vram_rd_data_2r;
    pal_rd_data_3r <= pal_rd_data_2r;
end
always @(posedge clk_i) begin
    pix_x_4r <= pix_x_3r;
    pix_y_4r <= pix_y_3r;
    vram_rd_data_4r <= vram_rd_data_3r;
    pal_rd_data_4r <= pal_rd_data_3r;
end
always @(posedge clk_i) begin
    case(pix_x_i[2:0])
        3'b000: begin
            tile_n <= vram_rd_data_4r[7:0];
            color_n <= vram_rd_data_4r[15:8];
        end
        3'b001: begin
            tile_n <= vram_rd_data_4r[15:8];
            color_n <= vram_rd_data_4r[7:0];
        end
        3'b010: begin
            tile_n <= vram_rd_data_4r[23:16];
            color_n <= vram_rd_data_4r[15:8];
        end
        3'b011: begin
            tile_n <= vram_rd_data_4r[31:24];
            color_n <= vram_rd_data_4r[23:16];
        end
        3'b100: begin
            tile_n <= vram_rd_data_4r[39:32];
            color_n <= vram_rd_data_4r[31:24];
        end
        3'b101: begin
            tile_n <= vram_rd_data_4r[47:40];
            color_n <= vram_rd_data_4r[39:32];
        end
        3'b110: begin
            tile_n <= vram_rd_data_4r[55:48];
            color_n <= vram_rd_data_4r[47:40];
        end
        3'b111: begin
            tile_n <= vram_rd_data_4r[63:56];
            color_n <= vram_rd_data_4r[55:48];
        end
    endcase
end
always @(posedge clk_i) begin
    tile_0r <= tile_n;
    tile_1r <= tile_0r;
    tile_2r <= tile_1r;
    tile_3r <= tile_2r;
    tile_4r <= tile_3r;
end
always @(posedge clk_i) begin
    color_0r <= color_n;
    color_1r <= color_0r;
    color_2r <= color_1r;
    color_3r <= color_2r;
    color_4r <= color_3r;
end
always @(posedge clk_i) begin
    vram_addr_o <= tilebase_i + tile_4r;
end
always @(posedge clk_i) begin
    delay_o <= pix_x_4r[9:3];
end
always @(posedge clk_i) begin
    if(color_4r == 8'h00) begin
        pal_addr_o <= 8'h00;
    end
    else begin
        pal_addr_o <= {color_4r[7:3], pix_y_4r[2:0]};
    end
end
always @(posedge clk_i) begin
    col_o <= pal_rd_data_4r;
end
endmodule

