module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;
input [7:0]request_floor; 
input [7:0]in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 
output direction; 
output complete;
output door_alert;
output weight_alert;
output [7:0] out_current_floor;
reg direction_reg;
reg complete_reg;
reg door_alert_reg;
reg weight_alert_reg;
reg [7:0] current_floor_reg;
assign direction = direction_reg;
assign complete = complete_reg;
assign door_alert = door_alert_reg;
assign weight_alert = weight_alert_reg;
assign out_current_floor = current_floor_reg;
always @(posedge clk)
begin
if(reset)
begin
current_floor_reg <= in_current_floor;
direction_reg <= 1'b1;
complete_reg <= 1'b0;
door_alert_reg <= 1'b0;
weight_alert_reg <= 1'b0;
end
else
begin
if(request_floor > current_floor_reg)
begin
current_floor_reg <= current_floor_reg + 1;
direction_reg <= 1'b1;
complete_reg <= 1'b0;
door_alert_reg <= 1'b0;
weight_alert_reg <= 1'b0;
end
else if(request_floor < current_floor_reg)
begin
current_floor_reg <= current_floor_reg - 1;
direction_reg <= 1'b0;
complete_reg <= 1'b0;
door_alert_reg <= 1'b0;
weight_alert_reg <= 1'b0;
end
else if(request_floor == current_floor_reg)
begin
current_floor_reg <= current_floor_reg;
direction_reg <= direction_reg;
complete_reg <= 1'b1;
door_alert_reg <= 1'b0;
weight_alert_reg <= 1'b0;
end
else if(over_time == 1'b1)
begin
current_floor_reg <= current_floor_reg;
direction_reg <= direction_reg;
complete_reg <= 1'b0;
door_alert_reg <= 1'b1;
weight_alert_reg <= 1'b0;
end
else if(over_weight == 1'b1)
begin
current_floor_reg <= current_floor_reg;
direction_reg <= direction_reg;
complete_reg <= 1'b0;
door_alert_reg <= 1'b0;
weight_alert_reg <= 1'b1;
end
end
end
endmodule

