module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
);
//------------------------------------------------------------------------------
// Local parameters
//------------------------------------------------------------------------------
localparam STATE_RESET = 2'd0;
localparam STATE_IDLE = 2'd1;
localparam STATE_RUNNING = 2'd2;
localparam STATE_COMPLETE = 2'd3;
//------------------------------------------------------------------------------
// Registers
//------------------------------------------------------------------------------
reg [1:0] current_state;
reg [1:0] next_state;
//------------------------------------------------------------------------------
// State machine
//------------------------------------------------------------------------------
always @(posedge clk) begin
    if (resetn == 1'b0) begin
        current_state <= STATE_RESET;
    end else begin
        current_state <= next_state;
    end
end
always @(*) begin
    case (current_state)
        STATE_RESET: begin
            if (go == 1'b1) begin
                next_state = STATE_RUNNING;
            end else begin
                next_state = STATE_IDLE;
            end
        end
        STATE_IDLE: begin
            if (go == 1'b1) begin
                next_state = STATE_RUNNING;
            end else begin
                next_state = STATE_IDLE;
            end
        end
        STATE_RUNNING: begin
            if (WREADY == 1'b1) begin
                next_state = STATE_COMPLETE;
            end else begin
                next_state = STATE_RUNNING;
            end
        end
        STATE_COMPLETE: begin
            next_state = STATE_IDLE;
        end
        default: begin
            next_state = STATE_RESET;
        end
    endcase
end
//------------------------------------------------------------------------------
// Outputs
//------------------------------------------------------------------------------
always @(*) begin
    case (current_state)
        STATE_RESET: begin
            WVALID = 1'b0;
            WSTRB = 4'b1111;
            done = 1'b0;
        end
        STATE_IDLE: begin
            WVALID = 1'b0;
            WSTRB = 4'b1111;
            done = 1'b0;
        end
        STATE_RUNNING: begin
            WVALID = 1'b1;
            WSTRB = 4'b1111;
            done = 1'b0;
        end
        STATE_COMPLETE: begin
            WVALID = 1'b0;
            WSTRB = 4'b1111;
            done = 1'b1;
        end
        default: begin
            WVALID = 1'b0;
            WSTRB = 4'b1111;
            done = 1'b0;
        end
    endcase
end
assign WDATA = data;
endmodule

module curr_floor_reg(
output reg [3:0] curr_floor,
input wire wr,
input wire reset,
input wire clk,
input wire [3:0] new_floor
);
