always @(posedge clk) begin
    if (reset) begin
        curr_floor_reg <= 4'b0;
    end
    else begin
        if (wr) begin
            curr_floor_reg <= new_floor;
        end
    end
end
// --------------------------------------------------------------------------- //
// 4-bit register with synchronous clk and reset (zero on reset)              //
// --------------------------------------------------------------------------- //
