// Mux between register output and zero (zero on reset)                       //
// --------------------------------------------------------------------------- //
always @(*) begin
    if (reset) begin
        curr_floor = 4'b0;
    end
    else begin
        curr_floor = curr_floor_next;
    end
end
// --------------------------------------------------------------------------- //
// --------------------------- End of curr_floor_reg ------------------------- //
// --------------------------------------------------------------------------- //
endmodule

