// The frequency of the output clk will be 
// one divided by the number of cycles.
//
// The frequency will be:
//   f = 50Mhz / (2*n)
// where n is the number of cycles.
//
// In this case, the frequency will be:
//   f = 50Mhz / (2*10000)
//   f = 1Hz
//--------------------------------------------
module clkdivider(
input wire clk,
output wire Hz5000
);
reg freq = 0;
reg [31:0] count = 0;
always @(posedge clk)
begin
	if (count == 9999)
	begin
		count <= 0;
		freq <= ~freq;
	end
	else
	begin
		count <= count + 1;
	end
end
assign Hz5000 = freq;
endmodule

