module parallel_if();
  reg [3:0] counter = 4'b0000;
  reg up_en = 1'b0;
  reg down_en = 1'b0;
  reg reset = 1'b0;
  reg enable = 1'b0;
  always @(counter or up_en or down_en or reset or enable) begin
    if (reset == 1'b1) begin
      counter <= 4'b0000;
    end else if (enable == 1'b1) begin
      if (up_en == 1'b1) begin
        counter <= counter + 1;
      end else if (down_en == 1'b1) begin
        counter <= counter - 1;
      end
    end
  end
endmodule

