module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
    reg [7:0] r_scan_code = 0;
    reg [3:0] counter = 0;
    reg ready = 0;
    reg parity = 0;
    reg stop = 0;
    assign scan_ready = ready;
    assign scan_code = r_scan_code;
    always @(negedge i_clock) begin
        if (reset) begin
            counter <= 0;
            parity <= 0;
            stop <= 0;
            ready <= 0;
        end else begin
            if (counter < 8) begin
                parity <= parity ^ i_data;
                r_scan_code[counter] <= i_data;
                counter <= counter + 1;
            end else if (counter == 8) begin
                if (parity == i_data) begin
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                end
            end else if (counter == 9) begin
                stop <= i_data;
                counter <= counter + 1;
            end else begin
                if (stop == 1) begin
                    ready <= 1;
                end else begin
                    ready <= 0;
                end
                counter <= 0;
            end
        end
    end
endmodule

