module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;
input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [15:0] datainmem [0:64*16-1];
reg [15:0] dataoutmem [0:16-1];
reg [15:0] datamem [0:1024*16-1];
integer i;
always @(posedge clk) begin
    if (rst) begin
        for (i = 0; i < 1024*16; i = i + 1) begin
            datamem[i] <= 0;
        end
        for (i = 0; i < 64*16; i = i + 1) begin
            datainmem[i] <= 0;
        end
        for (i = 0; i < 16; i = i + 1) begin
            dataoutmem[i] <= 0;
        end
    end
    else begin
        if (wren) begin
            for (i = 0; i < 64*16; i = i + 1) begin
                datainmem[i] <= datain[i*16+15:i*16];
            end
            for (i = 0; i < 64*16; i = i + 1) begin
                datamem[address1 + i*inputsize] <= datainmem[i];
            end
        end
        if (rden) begin
            for (i = 0; i < 16; i = i + 1) begin
                dataoutmem[i] <= datamem[address2 + i*16];
            end
            dataout <= {dataoutmem[0], dataoutmem[1], dataoutmem[2], dataoutmem[3],
                        dataoutmem[4], dataoutmem[5], dataoutmem[6], dataoutmem[7],
                        dataoutmem[8], dataoutmem[9], dataoutmem[10], dataoutmem[11],
                        dataoutmem[12], dataoutmem[13], dataoutmem[14], dataoutmem[15]};
        end
    end
end
endmodule

