    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
    localparam DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [DEPTH_BITS-1:0] index;
    reg read_d, write_d;
    reg empty, full;
    wire read_pulse, write_pulse;
    assign empty_n = ~empty;
    assign full_n  = ~full;
    assign dout    = mem[index];
    assign read_pulse = read & empty_n;
    assign write_pulse = write & full_n;
    always @(posedge clk) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= 0;
            read_d <= 0;
            write_d <= 0;
        end else begin
            read_d <= read;
            write_d <= write;
            if (read_pulse & ~write_pulse) begin
                if (index == 0) begin
                    empty <= 1'b1;
                    full <= 1'b0;
                end else begin
                    empty <= 1'b0;
                    if (index != DEPTH-1)
                        full <= 1'b0;
                    index <= index - 1;
                end
            end else if (write_pulse & ~read_pulse) begin
                index <= index + 1;
                if (index == 1) begin
                    empty <= 1'b0;
                    full <= 1'b1;
                end else begin
                    full <= 1'b0;
                    if (index != DEPTH)
                        empty <= 1'b0;
                end
            end else if (write_pulse & read_pulse) begin
                index <= index;
                empty <= 1'b0;
                full <= 1'b0;
            end
            if (write_pulse)
                mem[index] <= din;
        end
    end
endmodule

