			if (counter < 6'd32) begin
				remainder_internal_temp = remainder_internal << 1;
				remainder_internal_temp[0] = divider[31];
				if (remainder_internal_temp >= divisor) begin
					remainder_internal_temp = remainder_internal_temp - divisor;
					result_internal_temp = result_internal << 1;
					result_internal_temp[0] = 1'b1;
				end
				else begin
					result_internal_temp = result_internal << 1;
					result_internal_temp[0] = 1'b0;
				end
				counter = counter + 6'b1;
				remainder_internal <= remainder_internal_temp;
				result_internal <= result_internal_temp;
			end
			else begin
				done_internal <= 1'b1;
				new_input <= 1'b1;
			end
		end
	end
	assign done = done_internal;
	assign result = result_internal;
	assign remainder = remainder_internal;
endmodule

