module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
);
parameter PERIOD = 8;
reg [31:0] duty_reg;
reg [31:0] counter;
always @(posedge clk) begin
   if (rst == 1'b1) begin
      duty_reg <= duty;
      counter <= 32'b0;
      pwm_out <= 1'b0;
   end
   else begin
      if (counter < duty_reg)
         pwm_out <= 1'b1;
      else
         pwm_out <= 1'b0;
      counter <= counter + 1;
      if (counter == PERIOD - 1) begin
         counter <= 32'b0;
         duty_reg <= duty;
      end
   end
end
endmodule

