module is designed to synchronize an asynchronous input with a system clock. It uses two internal registers to minimize metastability. The module takes a system clock (clk), an asynchronous input (async_in), and a reset signal (reset) as inputs. It outputs a synchronized signal (sync_out) that is stable with the system clock. 
`timescale 1ns / 1ps
module synchronize(
    input clk,
    input async_in,
    input reset,
    output reg sync_out
    );
reg q1,q2;
always @(posedge clk or posedge reset)
if (reset) begin
    q1 <= 1'b0;
    q2 <= 1'b0;
end
else begin
    q1 <= async_in;
    q2 <= q1;
    sync_out <= q2;
end
endmodule

module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 8;
parameter level = 4;
reg [size-1 : 0] a_int [level-1 : 0];
reg [size-1 : 0] b_int [level-1 : 0];
reg [2*size-1 : 0] pdt_int [level-1 : 0];
integer i;
always @(posedge clk) begin
    a_int[0] <= a;
    b_int[0] <= b;
    pdt_int[0] <= a * b;
    for (i = 1; i < level; i = i + 1) begin
        a_int[i] <= a_int[i-1];
        b_int[i] <= b_int[i-1];
        pdt_int[i] <= a_int[i-1] * b_int[i-1];
    end
end
assign pdt = pdt_int[level-1];
endmodule

