module that performs a 1-bit data streaming width converter with a handshake protocol. It acts as a buffer or FIFO, allowing data to flow between two interfaces with synchronous valid/acknowledge signals. The module is parameterizable, allowing the DataWidth to be specified during module instantiation. 
`timescale 1ns / 1ps
module StreamingDataWidthConverter_Batch_5_regslice_both_w1
#(parameter 
    DataWidth=1
)(
    input ap_clk ,
    input ap_rst,
    input data_in , 
    input vld_in , 
    output ack_in ,
    output data_out, 
    output vld_out,
    input ack_out,
    output apdone_blk
);
// FSM
localparam IDLE = 2'd0;
localparam PAYLOAD_A = 2'd1;
localparam PAYLOAD_B = 2'd2;
localparam WAIT = 2'd3;
reg [1:0] state;
reg [1:0] nxt_state;
// control
reg sel_rd;
reg sel_wr;
// payload
reg [DataWidth-1:0] A_V_data_1;
reg [DataWidth-1:0] B_V_data_1;
reg [DataWidth-1:0] A_V_data_1_M;
reg [DataWidth-1:0] B_V_data_1_M;
reg [DataWidth-1:0] A_V_data_1_state;
reg [DataWidth-1:0] B_V_data_1_state;
// control
always @(posedge ap_clk) begin
    if (ap_rst) begin
        state <= IDLE;
    end
    else begin
        state <= nxt_state;
    end
end
always @(*) begin
    case (state)
        IDLE: begin
            if (vld_in) begin
                nxt_state = PAYLOAD_A;
            end
            else begin
                nxt_state = IDLE;
            end
        end
        PAYLOAD_A: begin
            if (ack_out) begin
                nxt_state = PAYLOAD_B;
            end
            else begin
                nxt_state = PAYLOAD_A;
            end
        end
        PAYLOAD_B: begin
            if (ack_out) begin
                nxt_state = PAYLOAD_A;
            end
            else begin
                nxt_state = PAYLOAD_B;
            end
        end
        WAIT: begin
            nxt_state = IDLE;
        end
        default: begin
            nxt_state = IDLE;
        end
    endcase
end
always @(*) begin
    case (state)
        IDLE: begin
            sel_rd = 1'b0;
            sel_wr = 1'b0;
        end
        PAYLOAD_A: begin
            sel_rd = 1'b0;
            sel_wr = 1'b1;
        end
        PAYLOAD_B: begin
            sel_rd = 1'b1;
            sel_wr = 1'b0;
        end
        WAIT: begin
            sel_rd = 1'b0;
            sel_wr = 1'b0;
        end
        default: begin
            sel_rd = 1'b0;
            sel_wr = 1'b0;
        end
    endcase
end
// control
assign ack_in = sel_rd | (state == WAIT);
assign vld_out = sel_wr;
assign apdone_blk = (state == WAIT);
// payload
always @(posedge ap_clk) begin
    if (ap_rst) begin
        A_V_data_1 <= 0;
        B_V_data_1 <= 0;
        A_V_data_1_state <= 0;
        B_V_data_1_state <= 0;
    end
    else begin
        if (vld_in & sel_wr) begin
            A_V_data_1 <= data_in;
            A_V_data_1_state <= 1;
        end
        if (ack_out & sel_rd) begin
            B_V_data_1 <= A_V_data_1;
            B_V_data_1_state <= A_V_data_1_state;
            A_V_data_1_state <= 0;
        end
    end
end
// combinational output
assign data_out = B_V_data_1_M;
always @(*) begin
    if (B_V_data_1_state) begin
        B_V_data_1_M = B_V_data_1;
    end
    else begin
        B_V_data_1_M = 0;
    end
end
endmodule

