module Processor(
    input CLK,
    input print,        
    input [7:0] data,   

    output reg RW = 0,      
    output reg [7:0] Din,   
    output reg ADDR,        
    input IRQ,          
    input [7:0] Dout
    );
    reg [7:0] Din_reg = 0;
    reg RW_reg = 0;
    reg ADDR_reg = 0;
    reg [7:0] data_reg = 0;
    reg [1:0] state = 0;
    reg [1:0] next_state = 0;
    reg [1:0] delay = 0;
    reg [1:0] next_delay = 0;
    always @(posedge CLK) begin
        state <= next_state;
        delay <= next_delay;
        RW <= RW_reg;
        ADDR <= ADDR_reg;
        Din <= Din_reg;
        data_reg <= data;
    end
    always @(*) begin
        next_delay = delay - 1;
        if (delay == 0) begin
            next_state = 0;
        end else begin
            next_state = state;
        end
        if (print == 1) begin
            RW_reg = 1;
            ADDR_reg = 1;
            Din_reg = data_reg;
            next_delay = 2;
        end else if (delay == 1) begin
            RW_reg = 0;
            ADDR_reg = 0;
            Din_reg = 0;
        end
        if (IRQ == 1 && Dout == 8'b00001111) begin
            RW_reg = 1;
            ADDR_reg = 0;
            Din_reg = data_reg;
            next_delay = 2;
        end
    end
endmodule

