module mash(
  din,
  dout)
;
  input [63:0]din;
  output [31:0]dout;
  wire [31:0]even_bits;
  wire [31:0]odd_bits;
  assign dout = even_bits | odd_bits;
  genvar i;
  generate
    for (i = 0; i <= 31; i = i + 1) begin : mash_logic
      assign odd_bits[i] = din[2 * i + 1];
      assign even_bits[i] = din[2 * i];
    end
  endgenerate
endmodule

