    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
    reg[31:0] x_var;
    reg[31:0] y_var;
    reg[31:0] u_var;
    wire[31:0] temp;
    assign Xoutport = x_var;
    assign Youtport = y_var;
    assign Uoutport = u_var;
    assign temp = x_var + DXport;
    always @(posedge CLK or posedge reset) begin
        if (reset) begin
            x_var <= 0;
            y_var <= 0;
            u_var <= 0;
        end else begin
            if (x_var < Aport) begin
                x_var <= temp;
                y_var <= Yinport + (Uinport * DXport);
                u_var <= Uinport + (Yinport * DXport);
            end
        end
    end
endmodule

