module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
    wire [16:0] tmp;
    // 17-bit sign-extended input
    assign tmp = {{3{data_i[13]}}, data_i};
    // Combinational logic
    always @(*) begin
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = {tmp[15:0], 1'b0};
            2'b10: data_o = {tmp[14:0], 2'b00};
            2'b11: data_o = {tmp[13:0], 3'b000};
        endcase
    end
endmodule

