module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
    reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    wire ena_int;
    assign ena_int = ena & updown;
    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin: bit_counter
            if (i == 0) begin
                always @(posedge clk, posedge rst) begin
                    if (rst) begin
                        cnt[i] <= 1'b0;
                    end else if (ena_int) begin
                        cnt[i] <= ~cnt[i];
                    end
                end
            end else begin
                always @(posedge clk, posedge rst) begin
                    if (rst) begin
                        cnt[i] <= 1'b0;
                    end else if (enable_wires[i - 1]) begin
                        cnt[i] <= ~cnt[i];
                    end
                end
            end
        end
    endgenerate
    assign enable_wires[BITS - 1] = ena;
    generate
        for (i = 0; i < BITS - 1; i = i + 1) begin: enable_prop
            assign enable_wires[i] = enable_wires[i + 1] & ~cnt[i + 1];
        end
    endgenerate
    assign ovf = cnt[0] ^ cnt[1];
    assign out = cnt;
endmodule

