module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
		reg [31:0] bcd;
		integer i;
		always @(binary)
		begin
			bcd = 0;
			for (i = 0; i < 16; i = i + 1)
			begin
				bcd = {bcd[30:0], binary[15 - i]};
				if (i < 15 && bcd[3:0] > 4)
					bcd[3:0] = bcd[3:0] + 3;
				if (i < 15 && bcd[7:4] > 4)
					bcd[7:4] = bcd[7:4] + 3;
				if (i < 15 && bcd[11:8] > 4)
					bcd[11:8] = bcd[11:8] + 3;
				if (i < 15 && bcd[15:12] > 4)
					bcd[15:12] = bcd[15:12] + 3;
				if (i < 15 && bcd[19:16] > 4)
					bcd[19:16] = bcd[19:16] + 3;
				if (i < 15 && bcd[23:20] > 4)
					bcd[23:20] = bcd[23:20] + 3;
				if (i < 15 && bcd[27:24] > 4)
					bcd[27:24] = bcd[27:24] + 3;
				if (i < 15 && bcd[31:28] > 4)
					bcd[31:28] = bcd[31:28] + 3;
			end
			bcd = bcd >> 1;
		end
		assign b = bcd[3:0];
		assign s = bcd[7:4];
		assign g = bcd[11:8];
		assign q = bcd[15:12];
endmodule

module, risc_v_32_mem, is designed to handle memory load operations for a 32-bit RISC-V processor. It takes a memory address (m_addr), data from memory (d_f_mem), and an instruction decode signal (inst_decode) to determine the type of load operation. The module then outputs the appropriately formatted data (mem_out) based on the instruction and address alignment. The instruction decode bits (i_lw, i_lbu, i_lb, i_lhu, i_lh) determine whether to load a word, byte, or half-word, with or without sign extension. The address bits are used to align the data correctly, and the module uses combinational logic to produce the output without any sequential state.
`timescale 1ns / 1ps
module risc_v_32_mem(m_addr,d_f_mem,inst_decode,mem_out);
input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
	output reg [31:0] mem_out;
	wire i_lw,i_lbu,i_lb,i_lhu,i_lh;
	wire [1:0] a_bit;
	assign {i_lw,i_lbu,i_lb,i_lhu,i_lh} = inst_decode[36:32];
	assign a_bit = m_addr[1:0];
	always @(*) begin
		if(i_lw) begin
			mem_out = d_f_mem;
		end
		else if(i_lbu) begin
			case(a_bit)
				2'b00: mem_out = {24'b0,d_f_mem[7:0]};
				2'b01: mem_out = {24'b0,d_f_mem[15:8]};
				2'b10: mem_out = {24'b0,d_f_mem[23:16]};
				2'b11: mem_out = {24'b0,d_f_mem[31:24]};
			endcase
		end
		else if(i_lb) begin
			case(a_bit)
				2'b00: mem_out = {{24{d_f_mem[7]}},d_f_mem[7:0]};
				2'b01: mem_out = {{24{d_f_mem[15]}},d_f_mem[15:8]};
				2'b10: mem_out = {{24{d_f_mem[23]}},d_f_mem[23:16]};
				2'b11: mem_out = {{24{d_f_mem[31]}},d_f_mem[31:24]};
			endcase
		end
		else if(i_lhu) begin
			case(a_bit)
				2'b00: mem_out = {16'b0,d_f_mem[15:0]};
				2'b10: mem_out = {16'b0,d_f_mem[31:16]};
				default: mem_out = 32'b0;
			endcase
		end
		else if(i_lh) begin
			case(a_bit)
				2'b00: mem_out = {{16{d_f_mem[15]}},d_f_mem[15:0]};
				2'b10: mem_out = {{16{d_f_mem[31]}},d_f_mem[31:16]};
				default: mem_out = 32'b0;
			endcase
		end
		else begin
			mem_out = 32'b0;
		end
	end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output [(DATA_WIDTH-1):0]  Read_Data_o
);
	// Declare the RAM variable
	reg [DATA_WIDTH-1:0] ram[MEMORY_DEPTH-1:0];
	wire [DATA_WIDTH-1:0] Var_i = 32'h10010000;
	wire [DATA_WIDTH-1:0] real_address;
	assign real_address = (Address_i - Var_i) >> 2;
	always @ (posedge clk)
	begin
		// Write
		if (Write_Enable_i)
			ram[real_address] <= Write_Data_i;
	end
	// Continuous assignment implies read returns NEW data.
	// This is the natural behavior of the TriMatrix memory
	// blocks in Single Port mode.  
	assign Read_Data_o = ram[real_address];
endmodule

