module Divider #(parameter Time=20)
(
    input I_CLK,
    output reg O_CLK
);
    reg [10:0] counter = 0;
    always @(posedge I_CLK) begin
        if (counter >= Time/2-1) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end
    always @(posedge I_CLK) begin
        if (counter >= Time/2-1) begin
            O_CLK <= ~O_CLK;
        end else begin
            O_CLK <= O_CLK;
        end
    end
endmodule

