module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
);
reg [15:0] rd_compl_tag_reg;
reg rd_compl_start_reg;
reg rd_compl_done_reg;
reg bm_tag_valid;
reg [15:0] bm_tag_reg;
reg bm_done_reg;
wire [15:0] tag_out;
wire done_out;
always @(posedge CLK)
begin
    if (RESET)
    begin
        rd_compl_tag_reg <= 16'h0;
        rd_compl_start_reg <= 1'b0;
        rd_compl_done_reg <= 1'b0;
        bm_tag_valid <= 1'b0;
        bm_tag_reg <= 16'h0;
        bm_done_reg <= 1'b0;
    end
    else
    begin
        rd_compl_tag_reg <= RD_COMPL_TAG;
        rd_compl_start_reg <= RD_COMPL_START;
        rd_compl_done_reg <= RD_COMPL_DONE;
        bm_tag_valid <= (bm_tag_valid | BM_DONE);
        bm_tag_reg <= BM_TAG;
        bm_done_reg <= BM_DONE;
    end
end
assign tag_out = (rd_compl_start_reg) ? rd_compl_tag_reg : bm_tag_reg;
assign done_out = (rd_compl_start_reg) ? rd_compl_done_reg : bm_done_reg;
assign OP_DONE = done_out;
assign OP_TAG = tag_out;
endmodule

module takes a 64-bit floating point number and returns its floor.
// The computation is done in the FPGA's architecture, using
// conversion functions and the floor operation.
module BBFFloor(
    input  [63:0] in,
    output reg [63:0] out
);
    // This always block is "always" triggered whenever in/out changes
    // It then performs the floor operation on the input, converts it to
    // a real number and updates the output with the result.
    always @(in, out) begin
        // Convert 64-bit FP to real
        real in_real = $bitstoreal(in);
        // Apply floor operation
        real out_real = $floor(in_real);
        // Convert back to 64-bit FP and update output
        out = $realtobits(out_real);
    end
endmodule

