module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );
    input  clk;
    input  shiftnld;
    input  captnupdt;
    output mainclk;
    output updateclk;
    output capture;
    output update;
    wire mainclk;
    wire updateclk;
    wire capture;
    wire update;
    reg temp_mainclk = 1'b0;
    reg temp_updateclk = 1'b0;
    reg temp_capture = 1'b0;
    reg temp_update = 1'b0;
    always @(captnupdt or shiftnld or clk)
    begin
        case ({captnupdt, shiftnld})
            2'b00 :
            begin
                temp_mainclk = clk;
                temp_updateclk = 1'b0;
                temp_capture = 1'b0;
                temp_update = 1'b1;
            end
            2'b01 :
            begin
                temp_mainclk = clk;
                temp_updateclk = clk;
                temp_capture = 1'b0;
                temp_update = 1'b1;
            end
            2'b10 :
            begin
                temp_mainclk = clk;
                temp_updateclk = clk;
                temp_capture = 1'b1;
                temp_update = 1'b0;
            end
            2'b11 :
            begin
                temp_mainclk = clk;
                temp_updateclk = clk;
                temp_capture = 1'b1;
                temp_update = 1'b0;
            end
        endcase
    end
    and (mainclk, temp_mainclk, clk);
    and (updateclk, temp_updateclk, clk);
    and (capture, temp_capture, clk);
    and (update, temp_update, clk);
endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
reg [15:0] H_cnt;
wire Pout_de_w;
wire Pout_hs_w;
wire Pout_vs_w;
wire Rden_w;
always @(posedge I_pxl_clk or negedge I_rst_n) begin
    if(!I_rst_n) begin
        V_cnt <= 16'd0;
        H_cnt <= 16'd0;
    end
    else begin
        if(H_cnt == I_h_total - 1'b1) begin
            H_cnt <= 16'd0;
            if(V_cnt == I_v_total - 1'b1) begin
                V_cnt <= 16'd0;
            end
            else begin
                V_cnt <= V_cnt + 1'b1;
            end
        end
        else begin
            H_cnt <= H_cnt + 1'b1;
        end
    end
end
assign Pout_de_w = ((H_cnt >= I_h_bporch + I_h_res) && (H_cnt < I_h_total - I_h_sync)) && ((V_cnt >= I_v_bporch + I_v_res) && (V_cnt < I_v_total - I_v_sync));
assign Pout_hs_w = (H_cnt >= I_h_bporch + I_h_res) && (H_cnt < I_h_total - I_h_sync);
assign Pout_vs_w = (V_cnt >= I_v_bporch + I_v_res) && (V_cnt < I_v_total - I_v_sync);
assign Rden_w = (H_cnt < I_rd_hres) && (V_cnt < I_rd_vres);
always @(posedge I_pxl_clk or negedge I_rst_n) begin
    if(!I_rst_n) begin
        O_de <= 1'b0;
        O_hs <= 1'b0;
        O_vs <= 1'b0;
        O_rden <= 1'b0;
    end
    else begin
        O_de <= Pout_de_w;
        O_hs <= Pout_hs_w ^ I_hs_pol;
        O_vs <= Pout_vs_w ^ I_vs_pol;
        O_rden <= Rden_w;
    end
end
endmodule

