module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
	reg [3:0] step;
	reg [31:0] counter;
	wire auto_clk;
	wire wasReady;
	always @(posedge clk or posedge rst) begin
		if(rst) begin
			counter <= 0;
			readn <= 1;
		end
		else begin
			if(SW15) begin
				counter <= counter + 1;
				if(wasReady) begin
					readn <= 0;
				end
				else begin
					readn <= 1;
				end
			end
			else begin
				counter <= 0;
				readn <= 1;
			end
		end
	end
	always @(posedge clk or posedge rst) begin
		if(rst) begin
			step <= 0;
		end
		else begin
			if(keyReady) begin
				case(BTN_OK)
					4'b0001: step <= 1;
					4'b0010: step <= 2;
					4'b0100: step <= 4;
					4'b1000: step <= 8;
				endcase
			end
		end
	end
	assign wasReady = (counter[24] == 1) || (counter[4] == 1);
	assign auto_clk = (SW2) ? counter[24] : counter[4];
	assign Clk_CPU = (SW15) ? wasReady : auto_clk;
	always @(*) begin
		if(SW15) begin
			clkdiv = step;
		end
		else begin
			clkdiv = counter[31:26];
		end
	end
endmodule

