	inout vccd1,	
	inout vssd1,	
`endif
   output reg  CLK,
   input  wire VCO_IN,
   input  wire ENb_CP,
   input  wire ENb_VCO,
   input  wire REF
);
   // This is a stub to get a basic test running
   // The timing path in the test will fail
   // The "real" avsdpll has much more work to it
   real       ref_period;
   real       clk_period;
   real       clk_phase;
   integer    clk_delay;
   integer    clk_count;
   always @(posedge REF)
     begin
	clk_delay <= 0;
	clk_delay <= clk_delay + 1;
	if (clk_delay == 0)
	  begin
	     ref_period <= 1.0;
	     clk_period <= ref_period;
	     clk_phase <= 0.0;
	     clk_count <= 0;
	  end
	else
	  begin
	     ref_period <= ref_period * 1.01;
	     clk_phase <= clk_phase + 90.0;
	     if (clk_phase >= 360.0)
	       begin
		  clk_phase <= clk_phase - 360.0;
		  clk_count <= clk_count + 1;
	       end
	     clk_period <= clk_period * 1.01;
	     if (clk_count == 0)
	       clk_period <= ref_period;
	     else if (clk_count == 1)
	       clk_period <= ref_period * 0.99;
	     else if (clk_count == 2)
	       clk_period <= ref_period * 0.999;
	     else if (clk_count == 3)
	       clk_period <= ref_period * 0.9999;
	     else if (clk_count == 4)
	       clk_period <= ref_period * 0.99999;
	     else if (clk_count == 5)
	       clk_period <= ref_period * 0.999999;
	     else if (clk_count == 6)
	       clk_period <= ref_period * 0.9999999;
	     else if (clk_count == 7)
	       clk_period <= ref_period * 0.99999999;
	     else if (clk_count == 8)
	       clk_period <= ref_period * 0.999999999;
	     else if (clk_count == 9)
	       clk_period <= ref_period * 0.9999999999;
	     else if (clk_count == 10)
	       clk_period <= ref_period * 0.99999999999;
	     else if (clk_count == 11)
	       clk_period <= ref_period * 0.999999999999;
	     else if (clk_count == 12)
	       clk_period <= ref_period * 0.9999999999999;
	     else if (clk_count == 13)
	       clk_period <= ref_period * 0.99999999999999;
	     else if (clk_count == 14)
	       clk_period <= ref_period * 0.999999999999999;
	     else if (clk_count == 15)
	       begin
		  clk_period <= ref_period * 1.0;
		  clk_count <= 0;
	       end
	  end
