module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
    localparam DEPTH = 1 << DEPTH_BITS;
    reg                 empty;
    reg                 full;
    reg [DEPTH_BITS-1:0] index;
    reg [DATA_BITS-1:0]  mem [0:DEPTH-1];
    assign empty_n = ~empty;
    assign full_n  = ~full;
    wire                 read_i  = read  & empty_n;
    wire                 write_i = write & full_n;
    always @(posedge clk or posedge aclr)
        if (aclr)
            index <= {DEPTH_BITS{1'b0}};
        else if (read_i)
            index <= index + 1'b1;
        else if (write_i)
            index <= index - 1'b1;
    always @(posedge clk or posedge aclr)
        if (aclr) begin
            empty <= 1'b1;
            full  <= 1'b0;
        end else begin
            empty <= (index == {DEPTH_BITS{1'b0}}) | empty;
            full  <= (index == {DEPTH_BITS{1'b1}}) | full;
        end
    always @(posedge clk)
        if (write_i)
            mem[index] <= din;
    assign dout = mem[index - 1'b1];
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;       // Counter variable
reg pre;                // Previous state
//------------------------------------------------------------------------------
// This always block is triggered on the positive edge of clk (0->1)
// Once inside this block, it checks if the button input is equal to the 
// previous state. If they are equal, it means the button is still debouncing
// If not, we update the output with the current input value
//------------------------------------------------------------------------------
always @(posedge clk)
begin
    //--------------------------------------------------------------------------
    // This if-else statement controls the timer. If the timer has not reached
    // its maximum count, we increment it. If it has reached its maximum count,
    // we check the button input again
    //--------------------------------------------------------------------------
    if (timer < 1000000)
        timer <= timer + 1;
    else
    begin
        if (btn_input == pre)
            btn_output <= btn_input;
        timer <= 32'b0;
        pre <= btn_input;
    end
end
endmodule

