module generates the N-bit Gray code. The number of bits
// is specified by the parameter N. The module is parameterized,
// allowing any number of bits.
//
// The Gray code is a binary numeral system where two successive
// values differ in only one bit.
//
// The module is controlled by the clock and reset. On reset, the
// state is set to a known condition, while on clock, the state is
// updated according to the control logic.
//
// The module is designed as a sequential logic.
//
// The module accepts an enable signal that, when asserted,
// progresses the state. When not asserted, the state is paused.
//
// The module provides the output through the gray_out port.
//----------------------------------------------------------------------------
module gray_Nbits (clk, reset, enable, gray_out);
parameter N = 4; //Number of bits in the Gray code
parameter SIZE = N+1; //Auxiliary control bit
parameter Zeros = {SIZE{1'b0}}; // Initial state: 0000...
input wire clk, reset, enable;
output wire [N-1:0]gray_out;
reg [SIZE-1:0] state;
reg [SIZE-1:0] toggle;
integer i;
always @(posedge clk or posedge reset)
  if (reset)
    state <= Zeros;
  else
    if (enable)
      state <= state ^ toggle;
    else
      state <= state;
always @(state)
  begin
    toggle[0] = 1;
    for (i = 1; i < SIZE; i = i+1)
      toggle[i] = ^state[i-1:0];
  end
assign gray_out = state[SIZE-1:1];
endmodule

