module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);
input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]            mem[0:(1 << ADDR_WIDTH) - 1];
reg [DATA_WIDTH-1:0]            rdata;
reg [DATA_WIDTH-1:0]            bypass_reg;
reg                             bypass_used;
integer i;
always @(posedge clk) begin
    if (rst) begin
        if (CLEAR_ON_INIT) begin
            for (i = 0; i < (1 << ADDR_WIDTH); i = i + 1) begin
                mem[i] <= {DATA_WIDTH{1'b0}};
            end
        end
    end else begin
        if (we) begin
            mem[waddr] <= din;
        end
    end
end
always @* begin
    if (re) begin
        if ((waddr == raddr) && we && ENABLE_BYPASS && !bypass_used) begin
            rdata = din;
            bypass_used = 1;
        end else begin
            rdata = mem[raddr];
        end
    end else begin
        rdata = {DATA_WIDTH{1'b0}};
    end
end
always @(posedge clk) begin
    if (rst) begin
        bypass_used <= 0;
    end else begin
        if (re && ENABLE_BYPASS) begin
            bypass_used <= 0;
        end
    end
end
assign dout = rdata;
endmodule

