module maintains two internal registers to track the last two Fibonacci numbers and updates them on each clock cycle until the stopping condition is met. The final output is computed as the sum of these two registers.
`timescale 1 ns / 1 ns 
`celldefine 
module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
//Defination for Varables in the module
reg [7:0] SEQUENCE_I1, SEQUENCE_I2;
//Logicals
//Stops when the value 144 is reached
assign STOP = (SEQUENCE_I1 == 8'd144);
//Output
assign SEQUENCE = (SEQUENCE_I1 + SEQUENCE_I2);
//Sequential Circuits
always @(posedge CLK_IN, negedge RST_N)
begin
    if (!RST_N)
    begin
        SEQUENCE_I1 <= 8'b0;
        SEQUENCE_I2 <= 8'b1;
    end
    else if (!STOP)
    begin
        SEQUENCE_I1 <= SEQUENCE_I2;
        SEQUENCE_I2 <= SEQUENCE;
    end
end
endmodule

