module matrix5arb (
   		   input clk,
   		   input rst_n,
   		   input [4:0] req,
   		   output [4:0] grant
   		   );
   reg [4:0] 		       state, state_nxt;
   reg [4:0] 		       grant_nxt;
   always @(posedge clk or negedge rst_n)
     if (!rst_n)
       state <= 5'b00001;
     else
       state <= state_nxt;
   always @(state or req)
     begin
	grant_nxt = 5'b0;
	state_nxt = state;
	case (1'b1)
	  state[0]: begin
	     if (req[0])
	       grant_nxt = 5'b00001;
	     else
	       state_nxt = 5'b00010;
	  end
	  state[1]: begin
	     if (req[1])
	       grant_nxt = 5'b00010;
	     else
	       state_nxt = 5'b00100;
	  end
	  state[2]: begin
	     if (req[2])
	       grant_nxt = 5'b00100;
	     else
	       state_nxt = 5'b01000;
	  end
	  state[3]: begin
	     if (req[3])
	       grant_nxt = 5'b01000;
	     else
	       state_nxt = 5'b10000;
	  end
	  state[4]: begin
	     if (req[4])
	       grant_nxt = 5'b10000;
	     else
	       state_nxt = 5'b00001;
	  end
	endcase // case (state)
     end // always @ (state or req)
   assign grant = grant_nxt;
endmodule // matrix5arb

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);
 parameter DATA_WIDTH = 1;
 parameter INSERT_REGISTER = 1;
 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
`timescale 1ns/1ps
module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);
 parameter DATA_WIDTH = 1;
 parameter INSERT_REGISTER = 1;
 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
 generate
  if (INSERT_REGISTER == 1) begin
   reg [DATA_WIDTH-1:0] state_datain;
   reg state_datain_valid;
   reg [DATA_WIDTH-1:0] state_dataout;
   reg state_dataout_valid;
   always @(posedge clock) begin
    if (resetn == 1'b0) begin
     state_datain <= {DATA_WIDTH{1'b0}};
     state_datain_valid <= 1'b0;
     state_dataout <= {DATA_WIDTH{1'b0}};
     state_dataout_valid <= 1'b0;
    end else begin
     if (i_datain_valid == 1'b1 && o_datain_stall == 1'b0) begin
      state_datain <= i_datain;
      state_datain_valid <= 1'b1;
     end else begin
      state_datain <= {DATA_WIDTH{1'b0}};
      state_datain_valid <= 1'b0;
     end
     if (state_dataout_valid == 1'b1 && i_dataout_stall == 1'b0) begin
      state_dataout <= o_dataout;
      state_dataout_valid <= 1'b1;
     end else begin
      state_dataout <= {DATA_WIDTH{1'b0}};
      state_dataout_valid <= 1'b0;
     end
    end
   end
   always @(*) begin
    o_datain_stall <= i_dataout_stall;
    o_dataout <= state_datain;
    o_dataout_valid <= state_datain_valid;
   end
  end else begin
   always @(*) begin
    o_datain_stall <= i_dataout_stall;
    o_dataout <= i_datain;
    o_dataout_valid <= i_datain_valid;
   end
  end
 endgenerate
endmodule

