module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );
	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
	reg [6:0] data_reg;
	reg [3:0] data_regnum;
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			data_reg <= 7'd0;
			data_regnum <= 4'd0;
		end
		else begin
			if(data_in_sign) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1'b1;
			end
			else begin
				data_reg <= data_reg;
				data_regnum <= data_regnum;
			end
		end
	end
	assign data_ok = (data_reg == 7'd28 || data_reg == 7'd36) && data_regnum == 4'd8;
	reg [6:0] data_out_r;
	reg data_out_sign_r;
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			data_out_r <= 7'd0;
			data_out_sign_r <= 1'b0;
		end
		else begin
			if(data_valid) begin
				data_out_r <= data_out_r + 1'b1;
				data_out_sign_r <= 1'b1;
			end
			else begin
				data_out_r <= data_out_r;
				data_out_sign_r <= 1'b0;
			end
		end
	end
	assign data_out = data_out_r;
	assign data_out_sign = data_out_sign_r;
endmodule

module counter (rstn, clk, up, down, count);
parameter WIDTH = 8;
input rstn;
input clk;
input up;
input down;
output [WIDTH-1:0] count;
reg [WIDTH-1:0] count_int;
always @(posedge clk or negedge rstn) begin
    if (rstn == 1'b0) begin
        count_int <= {WIDTH{1'b0}};
    end else begin
        if (up == 1'b1) begin
            count_int <= count_int + 1;
        end else if (down == 1'b1) begin
            count_int <= count_int - 1;
        end
    end
end
assign count = count_int;
endmodule

