module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter	Divider=100000; // 0< Divider <= 2^27-1
reg	[26:0]	Count;
wire			Enable;
wire			Finished;
assign	Finished = (Count==Divider);
assign	Enable = (Count<Divider);
always @ (posedge Clock)	// Combinational Logic
	begin
		Timeout <= Enable;
	end
always @ (posedge Clock)	// Sequential Logic
	begin
		if (MR == 1)
			Count <= 0;
		else if (Finished == 1)
			Count <= 0;
		else if (Enable == 1)
			Count <= Count + 1;
	end
endmodule

