module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);
localparam ADD_STATE = 1'b0;
localparam INC_STATE = 1'b1;
input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;
always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else begin
        case(state)
            ADD_STATE: begin
                if(mode) begin
                    counter <= din + 2;
                    state <= INC_STATE;
                end
                else begin
                    counter <= din + 1;
                end
            end
            INC_STATE: begin
                if(!mode) begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
                else begin
                    counter <= counter + 1;
                end
            end
        endcase
    end
end
assign dout = counter;
endmodule

