module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
    localparam DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [DEPTH_BITS-1:0] index;
    wire [DEPTH_BITS-1:0] index_next;
    wire                  empty;
    wire                  full;
    wire [DATA_BITS-1:0]  din_used;
    wire [DATA_BITS-1:0]  dout_used;
    assign empty_n = ~empty;
    assign full_n  = ~full;
    assign index_next = index + (write & ~full) - (read & ~empty);
    assign empty = (index == 0);
    assign full  = (index == DEPTH - 1);
    assign din_used = din;
    assign dout_used = mem[index];
    assign dout = dout_used;
    always @(posedge clk, posedge aclr) begin
        if (aclr) begin
            index <= 0;
        end else begin
            index <= index_next;
            if (write & ~full) begin
                mem[index_next] <= din_used;
            end
        end
    end
    generate
        genvar i;
        for (i = 0; i < DEPTH - 1; i = i + 1) begin: udpAppMux_txLengthNetwork_fifo_shifter
            always @(posedge clk, posedge aclr) begin
                if (aclr) begin
                    mem[i] <= 0;
                end else begin
                    mem[i] <= mem[i + 1];
                end
            end
        end
    endgenerate
endmodule

