module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);
  reg [8:0] value;
  reg [8:0] value_1;
  reg  maybe_full;
  wire  do_enq;
  wire  do_deq;
  reg [31:0] ram [0:511];
  wire [31:0] ram_T_0;
  assign io_enq_ready = 1'h1;
  assign io_deq_valid = 1'h1;
  assign io_deq_bits = ram[value_1];
  assign ram_T_0 = io_enq_bits;
  assign do_enq = io_enq_valid & io_enq_ready;
  assign do_deq = io_deq_ready & io_deq_valid;
  always @(posedge clock) begin
    if (reset) begin
      value <= 9'h0;
      value_1 <= 9'h0;
      maybe_full <= 1'h0;
    end else begin
      if (do_enq) begin
        ram[value] <= ram_T_0;
        if (do_deq) begin
          value <= value + 1'h1;
          value_1 <= value_1 + 1'h1;
        end else begin
          value <= value + 1'h1;
          maybe_full <= 1'h1;
        end
      end else begin
        if (do_deq) begin
          value_1 <= value_1 + 1'h1;
          maybe_full <= 1'h0;
        end
      end
    end
  end
endmodule

module sr_latch(in, out, clk, set, reset);
	parameter WIDTH = 8;
	input [WIDTH-1:0] in;
	output reg [WIDTH-1:0] out;
	input clk, set, reset;
	// Latch re-initialization is done at startup, before the first clock edge,
	//  to prevent a race condition.
	// This also ensures that the latch is properly re-initialized when reset is asserted.
	//  (Blocking assignment makes this work.)
	// Sequential logic should use this latch in place of a basic SR latch.
	always @(posedge clk) begin
		if (reset) begin
			out <= 0;
		end else if (set) begin
			out <= in;
		end
	end
endmodule

