module Administrador_de_salidas(
    input [2:0] RY,
    input [7:0] RX,
    input [2:0] Num,
    input [1:0] Sel_Salidas,
    output reg [7:0] o_Dataout,
    output reg [7:0] o_Addressdata,
    output reg ReadWrite
);
// El bloque always@* describe el funcionamiento de la maquina de estados
// La logica descrita aqui es puramente combinacional y no requiere reset u operaciones de reloj
always@*
begin
    case(Sel_Salidas)
        2'b00:
        begin
            o_Dataout = 8'b0;
            o_Addressdata = 8'b0;
            ReadWrite = 1'b0;
        end
        2'b01:
        begin
            o_Dataout = 8'b0;
            o_Addressdata = RY[2:0];
            ReadWrite = 1'b0;
        end
        2'b10:
        begin
            o_Dataout = Num[2:0];
            o_Addressdata = RX;
            ReadWrite = 1'b1; // Seleccionar una operacion de escritura
        end
        2'b11:
        begin
            o_Dataout = RX;
            o_Addressdata = RY;
            ReadWrite = 1'b0; // Seleccionar una operacion de lectura
        end
        default:
        begin
            o_Dataout = 8'b0;
            o_Addressdata = 8'b0;
            ReadWrite = 1'b0;
        end
    endcase
end
endmodule

module called `echo_server_application_m_axis_read_package_reg_slice` that is designed to act as a regulator for an AXI stream interface. The module takes data from the slave interface (s_data and s_valid) and transfers it to the master interface (m_data and m_valid), while ensuring that data is not lost during the transfer process. The module uses a finite state machine (FSM) with three states (ZERO, ONE, TWO) to control the data transfer process. The FSM transitions between states based on the s_valid and m_ready signals to manage the flow of data from the slave to the master interface. The module also uses registers to stage data during the transfer process and a control signal to control the s_ready output. 
`timescale 1 ns / 1 ns
module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0] ZERO = 2'b00;
localparam [1:0] ONE  = 2'b01;
localparam [1:0] TWO  = 2'b10;
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;
reg [1:0] s_ready_t;
reg [1:0] state;
reg [1:0] next;
wire [N-1:0] m_data_s;
wire m_valid_s;
wire s_ready_s;
wire [N-1:0] data_p1_s;
wire [N-1:0] data_p2_s;
wire load_p1_s;
wire load_p2_s;
wire load_p1_from_p2_s;
wire s_ready_t_s;
wire [1:0] state_s;
wire [1:0] next_s;
assign m_data_s = data_p1;
assign m_valid_s = s_ready_t[1];
assign s_ready_s = ~s_ready_t[1] | m_ready;
assign data_p1_s = load_p1 ? s_data : data_p1;
assign data_p2_s = load_p2 ? s_data : data_p2;
assign load_p1_s = (state == ZERO) & s_valid;
assign load_p2_s = (state == ONE) & s_valid;
assign load_p1_from_p2_s = (state == TWO) & m_ready;
assign s_ready_t_s = load_p1_from_p2 ? 2'b01 : {s_ready_t[0], 1'b0};
assign state_s = next;
assign next_s = (state == ZERO) ? (s_valid ? ONE : ZERO) : 
                (state == ONE) ? (s_valid ? TWO : ONE) : 
                (state == TWO) ? (m_ready ? ONE : TWO) : ZERO;
always @(posedge clk)
begin
    if(reset)
    begin
        data_p1 <= 0;
        data_p2 <= 0;
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
        s_ready_t <= 0;
        state <= ZERO;
    end
    else
    begin
        data_p1 <= data_p1_s;
        data_p2 <= data_p2_s;
        load_p1 <= load_p1_s;
        load_p2 <= load_p2_s;
        load_p1_from_p2 <= load_p1_from_p2_s;
        s_ready_t <= s_ready_t_s;
        state <= state_s;
    end
end
assign m_data = m_data_s;
assign m_valid = m_valid_s;
assign s_ready = s_ready_s;
endmodule

