    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;
    reg [2:0] state, next;
    always @(posedge clk, negedge rst_n) begin
        if (!rst_n) state <= S1;
        else state <= next;
