module IF_stage #(parameter MEM_WIDTH=8, parameter WIDTH, parameter OFF_WIDTH=6)(clk, reset, addr, instr, jump, stall, jumpOffset);
	input clk, reset, jump, stall;
	output [WIDTH-1:0] instr;
	output [MEM_WIDTH-1:0] addr;
	input [OFF_WIDTH-1:0] jumpOffset;
	wire [WIDTH-1:0] instruction;
	wire [MEM_WIDTH-1:0] address;
	wire [MEM_WIDTH-1:0] signExtendOutput;
	reg [MEM_WIDTH-1:0] PC;
	reg [WIDTH-1:0] instruction_mem [2**MEM_WIDTH-1:0];
	signExtend signExtendUnit(jumpOffset, signExtendOutput);
	// PC register
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			PC <= 0;
		end
		else if (!stall) begin
			PC <= signExtendOutput;
		end
	end
	// Instruction memory
	assign address = PC;
	assign instr = instruction_mem[address];
	// Combinational logic for instruction memory
	always @(*) begin
		if (jump) begin
			instruction_mem[signExtendOutput] = 0;
		end
		else begin
			instruction_mem[PC] = 0;
		end
	end
	assign addr = PC;
endmodule
