module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
  reg [7:0]clkA_data;
  reg [2:0]SyncA_clkB;
  reg FlagToggle_clkA;
  reg [2:0]SyncA_clkA;
  reg FlagToggle_clkB;
  reg [7:0]clkB_data;
  assign FlagOut_clkB = FlagToggle_clkB ^ SyncA_clkB[2];
  assign dataB = clkB_data;
  always @(posedge clkA) begin
    clkA_data <= dataA;
    SyncA_clkA <= {SyncA_clkA[1:0], FlagToggle_clkB};
    if (FlagIn_clkA) begin
      FlagToggle_clkA <= ~FlagToggle_clkA;
    end
  end
  always @(posedge clkB) begin
    clkB_data <= clkA_data;
    SyncA_clkB <= {SyncA_clkB[1:0], SyncA_clkA[2]};
    if (SyncA_clkB[2] != SyncA_clkB[1]) begin
      FlagToggle_clkB <= ~FlagToggle_clkB;
    end
  end
endmodule

module implements a programmable delay circuit with a maximum delay of 31 clock cycles. It uses a 5-bit DELAY input to specify the delay length and provides the delayed output Q. The design employs multiple stages of delay using instances of another module, gh_delay, with increasing delay lengths (2, 4, 8, 16 clock cycles), which are combined to achieve the desired total delay. The circuit includes reset functionality through rst and srst signals, which clear the delay stages when activated. Internal signals D_d1 to D_d16 and Q_d1 to Q_d16 manage the data flow between these delay stages, with Q_d1 being the only registered internal signal to handle single-cycle delays. The final output Q is determined by the DELAY input, selecting either the direct input D or one of the delayed signals from the stages. The module effectively allows for flexible and precise control over the delay applied to the input signal D based on the DELAY configuration.
`verilog
module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
);
reg Q_d1;
wire D_d1;
wire Q_d2;
wire D_d2;
wire Q_d4;
wire D_d4;
wire Q_d8;
wire D_d8;
wire Q_d16;
wire D_d16;
always @(posedge CLK)
begin
  if(rst)
    Q_d1 <= 1'b0;
  else
  if(srst)
    Q_d1 <= 1'b0;
  else
    Q_d1 <= D;
end
assign D_d1 = Q_d1;
assign D_d2 = (DELAY[0]) ? D_d1 : Q_d1;
gh_delay #(.delay_ticks(2))
  delay_2(.CLK(CLK),
          .rst(rst),
          .srst(srst),
          .D(D_d2),
          .Q(Q_d2));
assign D_d4 = (DELAY[1]) ? D_d2 : Q_d2;
gh_delay #(.delay_ticks(4))
  delay_4(.CLK(CLK),
          .rst(rst),
          .srst(srst),
          .D(D_d4),
          .Q(Q_d4));
assign D_d8 = (DELAY[2]) ? D_d4 : Q_d4;
gh_delay #(.delay_ticks(8))
  delay_8(.CLK(CLK),
          .rst(rst),
          .srst(srst),
          .D(D_d8),
          .Q(Q_d8));
assign D_d16 = (DELAY[3]) ? D_d8 : Q_d8;
gh_delay #(.delay_ticks(16))
  delay_16(.CLK(CLK),
          .rst(rst),
          .srst(srst),
          .D(D_d16),
          .Q(Q_d16));
assign Q = (DELAY[4]) ? D_d16 : Q_d16;
endmodule
module gh_delay #
  (parameter delay_ticks = 2)
  (
   input wire CLK,
   input wire rst,
   input wire srst,
   input wire D,
   output reg Q
   );
   localparam ticks = delay_ticks/2;
   reg [ticks-1:0] counter;
   always @(posedge CLK)
   begin
     if(rst)
       Q <= 1'b0;
     else
     if(srst)
       Q <= 1'b0;
     else
     if(&counter)
       Q <= D;
     else
       Q <= Q;
   end
   always @(posedge CLK)
   begin
     if(rst)
       counter <= {ticks{1'b0}};
     else
     if(srst)
       counter <= {ticks{1'b0}};
     else
       counter <= counter + 1'b1;
   end
endmodule

