module countUD10L(
    input clk,
    input Up,
    input Dw,
    input reset,
    input LD,
    input [9:0] D,
    output [9:0] Q
    );
    wire UTC;
    wire DTC;
    countUD5L counter1(clk,Up,Dw,reset,LD,D[4:0],Q[4:0],UTC,DTC);
    countUD5L counter2(clk,Up,Dw,reset,LD,D[9:5],Q[9:5],DTC,);
endmodule
module countUD5L(
    input clk,
    input Up,
    input Dw,
    input reset,
    input LD,
    input [4:0] D,
    output reg [4:0] Q,
    output reg UTC,
    output reg DTC
    );
    always @(posedge clk)
    begin
        if(reset)
        begin
            Q <= 0;
            DTC <= 0;
            UTC <= 0;
        end
        else if(LD)
        begin
            Q <= D;
            DTC <= 0;
            UTC <= 0;
        end
        else
        begin
            if(Up & ~Dw)
            begin
                if(Q == 5'b11111)
                begin
                    Q <= 0;
                    DTC <= 0;
                    UTC <= 1;
                end
                else
                begin
                    Q <= Q + 1;
                    DTC <= 0;
                    UTC <= 0;
                end
            end
            else if(~Up & Dw)
            begin
                if(Q == 5'b00000)
                begin
                    Q <= 5'b11111;
                    DTC <= 1;
                    UTC <= 0;
                end
                else
                begin
                    Q <= Q - 1;
                    DTC <= 0;
                    UTC <= 0;
                end
            end
            else
            begin
                Q <= Q;
                DTC <= 0;
                UTC <= 0;
            end
        end
    end
endmodule

