(* X_CORE_INFO = "pe,Vivado 2020.2" *)
module pe(
    clk,
    rst,
    a,
    b,
    c)
;
  input clk;
  input rst;
  input [31:0]a;
  input [31:0]b;
  output reg [31:0]c;
  localparam MULT_WIDTH = 32'd32;
  localparam SUM_WIDTH = 32'd32;
  wire [63:0]product;
  assign product = a * b;
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      c <= 32'b00000000000000000000000000000000;
    end
    else begin
      c <= c + product[31:0];
    end
  end
endmodule

module testbench;
parameter A_WIDTH = 3;
parameter B_WIDTH = 3;
parameter TEST_COUNT = 100;
reg [A_WIDTH-1:0] A;
reg [B_WIDTH-1:0] B;
wire A_greater, A_equal, A_less;
integer i;
integer error = 0;
always @(*) begin
    $display("Testbench for 3-bit comparator");
    for (i = 0; i < TEST_COUNT; i = i + 1) begin
        A = $random % (2**A_WIDTH);
        B = $random % (2**B_WIDTH);
        if (A > B) begin
            if (!(A_greater && !A_equal && !A_less)) begin
                error = error + 1;
                $display("Error: Test case %d, expected A_greater", i);
            end
        end else if (A == B) begin
            if (!(A_greater && !A_equal && !A_less)) begin
                error = error + 1;
                $display("Error: Test case %d, expected A_equal", i);
            end
        end else begin
            if (!(!A_greater && !A_equal && A_less)) begin
                error = error + 1;
                $display("Error: Test case %d, expected A_less", i);
            end
        end
    end
    if (error == 0) begin
        $display("All %d test cases passed!", TEST_COUNT);
    end else begin
        $display("%d test cases failed out of %d", error, TEST_COUNT);
    end
end
endmodule

