module unidade_de_controle_ciclo_unico(
input wire [INSTR_WIDTH - 1:0] instrucao,
output wire [DP_CTRL_BUS_WIDTH - 1:0] controle
);
// parametros
parameter INSTR_WIDTH = 16;
parameter OPCODE_WIDTH = 4;
parameter DP_CTRL_BUS_WIDTH = 6;
// sinais
wire [OPCODE_WIDTH - 1:0] opcode;
reg [DP_CTRL_BUS_WIDTH - 1:0] controle_interno;
assign opcode = instrucao[INSTR_WIDTH - 1:INSTR_WIDTH - OPCODE_WIDTH];
assign controle = controle_interno;
// regras de controle
always @(*) begin
	case (opcode)
		4'b0000: controle_interno = 6'b100001;
		4'b0001: controle_interno = 6'b010100;
		4'b0010: controle_interno = 6'b001100;
		4'b0011: controle_interno = 6'b001101;
		4'b0100: controle_interno = 6'b001110;
