module cycloneiv_pciehip_pciexp_dcfiforam (data, wren, wraddress, rdaddress, wrclock, rdclock, q);
   parameter integer data_width = 32;
   parameter integer addr_width = 8;
   input[data_width - 1:0] data; 
   input wren; 
   input[addr_width - 1:0] wraddress; 
   input[addr_width - 1:0] rdaddress; 
   input wrclock; 
   input rdclock; 
   output[data_width - 1:0] q;
   reg[addr_width - 1:0] rdaddr_reg;
   reg[addr_width - 1:0] rdaddr_reg_h;
   reg[addr_width - 1:0] wraddr_reg;
   reg[addr_width - 1:0] wraddr_reg_h;
   reg wr_en_reg;
   reg wr_en_reg_h;
   reg[data_width - 1:0] mem [0:(1 << addr_width) - 1];
   reg[data_width - 1:0] q;
   always @(posedge wrclock)
   begin
      wraddr_reg <= wraddress;
      wraddr_reg_h <= wraddr_reg;
      wr_en_reg <= wren;
      wr_en_reg_h <= wr_en_reg;
      if (wr_en_reg_h == 1'b1)
         mem[wraddr_reg_h] <= data;
   end
   always @(posedge rdclock)
   begin
      rdaddr_reg <= rdaddress;
      rdaddr_reg_h <= rdaddr_reg;
   end
   always @(rdaddr_reg_h)
   begin
      q = mem[rdaddr_reg_h];
   end
endmodule

