module named SumCentroidValues that takes in three inputs: valueDado, valueX, and valueY. It also produces two outputs: o_valueX and o_valueY. The module uses two registers, s_valueX and s_valueY, to store intermediate results. These registers are updated based on the input signals and the conditions specified in the always block. The module's behavior is determined by the conditions evaluated on the most significant bits of its inputs. 
`timescale 1ns / 1ps
module SumCentroidValues(
input wire [Palavra - 1:0] valueDado,
input wire [PalavraXY - 1:0] valueX,
input wire [PalavraXY - 1:0] valueY,
output wire [PalavraXY - 1:0] o_valueX,
output wire [PalavraXY - 1:0] o_valueY
);
parameter Palavra = 64;
parameter PalavraXY = 32;
reg [PalavraXY - 1:0] s_valueX;
reg [PalavraXY - 1:0] s_valueY;
always @(valueDado or valueX or valueY) begin // abordagem combinacional
	if(valueDado[Palavra - 1] & valueX[PalavraXY - 1]) begin
		s_valueX = {32{1'b1}};
	end
	else begin
		s_valueX = valueDado[31:0] + valueX;
	end
	if(valueDado[Palavra - 1] & valueY[PalavraXY - 1]) begin
		s_valueY = {32{1'b1}};
	end
	else begin
		s_valueY = valueDado[31:0] + valueY;
	end
end
assign o_valueX = s_valueX;
assign o_valueY = s_valueY;
endmodule

