module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;
output red,yellow,green;
reg [1:0] state, next_state;
reg light;
parameter s0=2'b00, s1=2'b01, s2=2'b10, s3=2'b11;
always @(posedge clk or posedge reset)
begin
if(reset)
state<=s0;
else
state<=next_state;
end
always @(state)
begin
case(state)
s0:begin
light=1'b0;
next_state=s1;
end
s1:begin
light=1'b0;
next_state=s2;
end
s2:begin
light=1'b1;
next_state=s3;
end
s3:begin
light=1'b0;
next_state=s0;
end
endcase
end
assign red= (state==s0)?1'b1:1'b0;
assign yellow= (state==s2)?1'b1:1'b0;
assign green= (state==s3)?1'b1:1'b0;
endmodule

