module lpm_or (
    data,  
    result 
);
    input  [(lpm_size * lpm_width)-1:0] data;
    output [lpm_width-1:0] result;
    parameter lpm_width = 1;
    parameter lpm_size = 1;
    wire [lpm_width-1:0] result;
    wire [(lpm_size * lpm_width)-1:0] data;
    reg [lpm_width-1:0] temp_result;
    integer i, j;
`timescale 1ns/1ps
module lpm_or (
    data,  
    result 
);
    input  [(lpm_size * lpm_width)-1:0] data;
    output [lpm_width-1:0] result;
    parameter lpm_width = 1;
    parameter lpm_size = 1;
    wire [lpm_width-1:0] result;
    wire [(lpm_size * lpm_width)-1:0] data;
    reg [lpm_width-1:0] temp_result;
    integer i, j;
    always @(data)
    begin
        temp_result = {(lpm_width){1'b0}};
        for (i = 0; i < lpm_size; i = i + 1)
        begin
            for (j = 0; j < lpm_width; j = j + 1)
            begin
                temp_result[j] = temp_result[j] | data[(i * lpm_width) + j];
            end
        end
    end
    assign result = temp_result;
endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    parameter NUM_DIV = 6;
    reg clk_div;
    reg [15:0] cnt;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            cnt <= 16'd0;
            clk_div <= 1'b0;
        end
        else begin
            if (cnt < NUM_DIV / 2 - 1) begin
                cnt <= cnt + 16'd1;
            end
            else begin
                cnt <= 16'd0;
                clk_div <= ~clk_div;
            end
        end
    end
endmodule

