module priority_encoder(
input wire [3:0] data_in,
output wire [1:0] data_out,
output wire group_select
);
//internal wires
wire not_d1, not_d0, not_d2;
wire or_1, or_2, or_3;
//NOT gates for inverting data_in[1] and data_in[0]
not (not_d1, data_in[1]);
not (not_d0, data_in[0]);
//NOT gate for inverting data_in[2]
not (not_d2, data_in[2]);
//OR gates for determining data_out[1] and data_out[0]
or (or_1, data_in[2], data_in[3]);
or (or_2, data_in[1], data_in[3]);
or (or_3, data_in[1], data_in[2]);
//AND gates for determining group_select
and (group_select, data_in[0], not_d1, not_d0);
//outputs
and (data_out[1], or_1, not_d2);
and (data_out[0], or_2, not_d2, not_d0);
endmodule

