module uart (
   // Outputs
   data_out, done,
   // Inputs
   clk, rst_n, data_in, start
   ) ;
   input clk;
   input rst_n;
   input [7:0] data_in;
   input       start;
   output reg [7:0] data_out;
   output reg       done;
   // Beginning of automatic regs (for this module's undeclared outputs)
   reg [7:0]		data_out_reg;
   reg			done_reg;
   // End of automatics
   //
   // Baud rate generator
   //
   localparam BAUD_PERIOD = 10416;
   reg [13:0] baud_counter;
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 baud_counter <= 0;
      end else begin
	 if (baud_counter == BAUD_PERIOD) begin
	    baud_counter <= 0;
	 end else begin
	    baud_counter <= baud_counter + 1;
	 end
      end
   end
   //
   // State machine
   //
   localparam IDLE = 0;
   localparam START_BIT = 1;
   localparam DATA_BITS = 2;
   localparam PARITY_BIT = 3;
   localparam STOP_BIT = 4;
   reg [2:0] state;
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 state <= IDLE;
      end else begin
	 case (state)
	   IDLE: begin
	      if (start == 1'b1) begin
		 state <= START_BIT;
	      end
	   end
	   START_BIT: begin
	      if (baud_counter == BAUD_PERIOD) begin
		 state <= DATA_BITS;
	      end
	   end
	   DATA_BITS: begin
	      if (baud_counter == BAUD_PERIOD) begin
		 if (bit_counter == 7) begin
		    state <= PARITY_BIT;
		 end
	      end
	   end
	   PARITY_BIT: begin
	      if (baud_counter == BAUD_PERIOD) begin
		 state <= STOP_BIT;
	      end
	   end
	   STOP_BIT: begin
	      if (baud_counter == BAUD_PERIOD) begin
		 state <= IDLE;
	      end
	   end
	 endcase // case (state)
      end
   end
   //
   // Shift register
   //
   reg [7:0] shift_reg;
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 shift_reg <= 0;
      end else begin
	 if (state == IDLE) begin
	    shift_reg <= data_in;
	 end else if (state == START_BIT) begin
	    if (baud_counter == BAUD_PERIOD) begin
	       shift_reg <= 0;
	    end
	 end else if (state == DATA_BITS) begin
	    if (baud_counter == BAUD_PERIOD) begin
	       shift_reg <= {1'b0, shift_reg[7:1]};
	    end
	 end
      end
   end
   //
   // Bit counter
   //
   reg [2:0] bit_counter;
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 bit_counter <= 0;
      end else begin
	 if (state == DATA_BITS) begin
	    if (baud_counter == BAUD_PERIOD) begin
	       bit_counter <= bit_counter + 1;
	    end
	 end else begin
	    bit_counter <= 0;
	 end
      end
   end
   //
   // Parity bit
   //
   reg parity_bit;
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 parity_bit <= 0;
      end else begin
	 if (state == IDLE) begin
	    parity_bit <= ^data_in;
	 end
      end
   end
   //
   // Output
   //
   always @(posedge clk or negedge rst_n) begin
      if (rst_n == 1'b0) begin
	 done_reg <= 0;
	 data_out_reg <= 0;
      end else begin
	 case (state)
	   IDLE: begin
	      done_reg <= 0;
	   end
	   STOP_BIT: begin
	      if (baud_counter == BAUD_PERIOD) begin
		 done_reg <= 1;
		 data_out_reg <= shift_reg;
	      end
	   end
	 endcase // case (state)
      end
   end
   always @(posedge clk) begin
      done <= done_reg;
      data_out <= data_out_reg;
   end
endmodule

