//This module is used for the master part of the APB protocol
//It implements a FSM to manage the protocol for peripheral transactions
module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);   
//This is the Verilog code for APB_master module
//This module is used for the master part of the APB protocol
//It implements a FSM to manage the protocol for peripheral transactions
module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);   
//This is the state declaration section of the FSM
parameter IDLE = 2'b00, SETUP = 2'b01, ACCESS = 2'b10;
//This is the state register section of the FSM
reg [1:0] state, next_state;
//This is the sequential logic for the state register
always @(posedge PCLK or negedge PRESETn)
begin
  if(!PRESETn)
    state <= IDLE;
  else
    state <= next_state;
end
//This is the combinational logic for the next state logic
always @(*)
begin
  case(state)
    IDLE:
      if(Transfer && !PSLVERR)
        next_state = SETUP;
      else
        next_state = IDLE;
    SETUP:
      if(Transfer && !PSLVERR)
        next_state = ACCESS;
      else
        next_state = SETUP;
    ACCESS:
      if(Transfer && !PSLVERR)
        if(PREADY)
          next_state = SETUP;
        else
          next_state = ACCESS;
      else
        next_state = IDLE;
    default:
      next_state = IDLE;
  endcase
end
//This is the combinational logic for the output logic
always @(*)
begin
  PSELx = 1'b0;
  PENABLE = 1'b0;
  PWRITE = 1'b0;
  case(state)
    IDLE:
      if(Transfer && !PSLVERR)
        begin
          PSELx = 1'b1;
          PENABLE = 1'b0;
          PWRITE = Wr_Rd;
        end
    SETUP:
      if(Transfer && !PSLVERR)
        begin
          PSELx = 1'b1;
          PENABLE = 1'b0;
          PWRITE = Wr_Rd;
        end
    ACCESS:
      if(Transfer && !PSLVERR)
        begin
          PSELx = 1'b1;
          PENABLE = 1'b1;
          PWRITE = Wr_Rd;
        end
    default:
      begin
        PSELx = 1'b0;
        PENABLE = 1'b0;
        PWRITE = 1'b0;
      end
  endcase
end
//This is the sequential logic for the input capture logic
always @(posedge PCLK or negedge PRESETn)
begin
  if(!PRESETn)
    begin
      PADDR <= 5'b0;
      PWDATA <= 32'b0;
      read_data <= 32'b0;
    end
  else
    begin
      PADDR <= Address;
      PWDATA <= write_data;
      if(PSELx && PENABLE && PREADY && !PSLVERR)
        read_data <= PRDATA;
    end
end
endmodule

