module gates(
input wire a_i,
input wire b_i,
input wire c_i,
output wire out_o,
output wire out2_o,
output wire out3_o,
output wire out4_o,
output wire out5_o,
output wire out6_o,
output wire out7_o,
output wire out8_o
);
// This module is purely combinational
// All outputs depend only on inputs
// Example of a fundamental contradiction
// In a purely combinational circuit, there is no state
// and therefore no need for a clock
assign out_o = 1'b0;
assign out2_o = 1'b1;
// Example of redundancy
assign out3_o = a_i;
assign out4_o = a_i;
// Logical distributive law
// p. 298
assign out5_o = (a_i & b_i) | (a_i & ~b_i);
assign out6_o = (a_i | b_i) & (a_i | ~b_i);
// De Morgan law
// p. 298
assign out7_o = ~(a_i & b_i);
assign out8_o = ~(a_i | b_i);
endmodule

