module PulseCounter(
input wire clk,
output wire pulse
);
parameter BITS = 28;
parameter UPPER_BOUND = 28'hFFFFFFF;
reg [BITS-1:0] count = 0;
reg pulse_reg = 0;
always @(posedge clk) begin
  if (count == UPPER_BOUND) begin
    count <= 0;
    pulse_reg <= 1;
  end else begin
    count <= count + 1;
    pulse_reg <= 0;
  end
end
assign pulse = pulse_reg;
endmodule

