module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );
    input  clk;
    input  shiftnld;
    input  captnupdt;
    output mainclk;
    output updateclk;
    output capture;
    output update;
    reg mainclk_tmp;
    reg updateclk_tmp;
    reg capture_tmp;
    reg update_tmp;
    reg [1:0] state_out;
    always @(captnupdt or shiftnld or clk)
    begin : state_logic
        case ({captnupdt, shiftnld})
            2'b00 :  state_out = 2'b00;
            2'b01 :  state_out = 2'b01;
            2'b10 :  state_out = 2'b10;
            2'b11 :  state_out = 2'b11;
            default :  state_out = 2'b00;
        endcase
    end
    always @(posedge clk)
    begin : output_logic
        mainclk_tmp <= state_out[1];
        updateclk_tmp <= state_out[0];
        capture_tmp <= state_out[1] & state_out[0];
        update_tmp <= state_out[1] & ~state_out[0];
    end
    assign mainclk = mainclk_tmp & 1'b1;
    assign updateclk = updateclk_tmp & 1'b1;
    assign capture = capture_tmp & 1'b1;
    assign update = update_tmp & 1'b1;
endmodule

