wire YA, YB, YC, YD, YE, YF, YG, YH;
not(S0n, S0);
not(S1n, S1);
not(S2n, S2);
and(YA, A, S0n, S1n, S2n);
and(YB, B, S0, S1n, S2n);
and(YC, C, S0n, S1, S2n);
and(YD, D, S0, S1, S2n);
