module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
    parameter [7:0] START_BYTE = 8'h01;
    parameter [7:0] END_BYTE = 8'h04;
    parameter [7:0] MSG_DELAY = 8'h28;
    parameter [7:0] DELAY_COUNT = 8'h28;
    parameter [7:0] STATE_IDLE = 8'h00;
    parameter [7:0] STATE_LOAD_DATA = 8'h01;
    parameter [7:0] STATE_TRIGGER = 8'h02;
    parameter [7:0] STATE_POLL_BUSY = 8'h03;
    parameter [7:0] STATE_PAUSE = 8'h04;
    reg [7:0] state = STATE_IDLE;
    reg [7:0] data_index = 8'h00;
    reg [7:0] delay_count = 8'h00;
    reg run_test = 1'b0;
    reg trigger_high = 1'b0;
    always @(posedge clk_50M) begin
        run_test <= run_test_raw;
    end
    always @(posedge clk_50M) begin
        case (state)
            STATE_IDLE: begin
                if (run_test) begin
                    state <= STATE_LOAD_DATA;
                    data_index <= 8'h00;
                    delay_count <= 8'h00;
                end
            end
            STATE_LOAD_DATA: begin
                data_out <= "H";
                state <= STATE_TRIGGER;
            end
            STATE_TRIGGER: begin
                trigger_high <= 1'b1;
                state <= STATE_POLL_BUSY;
            end
            STATE_POLL_BUSY: begin
                if (!tx_busy) begin
                    if (data_index == 8'h0B) begin
                        state <= STATE_PAUSE;
                        delay_count <= 8'h00;
                    end else begin
                        state <= STATE_LOAD_DATA;
                        data_index <= data_index + 1;
                    end
                end
            end
            STATE_PAUSE: begin
                if (delay_count == MSG_DELAY) begin
                    state <= STATE_IDLE;
                end else begin
                    delay_count <= delay_count + 1;
                end
            end
        endcase
        if (trigger_high) begin
            trigger <= 1'b1;
            trigger_high <= 1'b0;
        end else begin
            trigger <= 1'b0;
        end
    end
endmodule

