module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
	reg [7:0] x_nxt; 
	reg [6:0] y_nxt; 
	reg clear; 
	reg clear_nxt; 
	reg [2:0] colour_nxt;
	always @(posedge clk) begin
		clear <= #1 clear_nxt;
		x <= #1 x_nxt;
		y <= #1 y_nxt;
		colour <= #1 colour_nxt;
	end
	always @(*) begin
		if (startGameEn) begin
			x_nxt = 8'b0;
			y_nxt = 7'b0;
			clear_nxt = 1'b1;
		end
		else begin
			if (x == 8'd159 && y == 7'd119) begin
				x_nxt = 8'b0;
				y_nxt = 7'b0;
				clear_nxt = 1'b0;
			end
			else if (x == 8'd159) begin
				x_nxt = 8'b0;
				y_nxt = y + 1'b1;
				clear_nxt = 1'b0;
			end
			else begin
				x_nxt = x + 1'b1;
				y_nxt = y;
				clear_nxt = 1'b0;
			end
		end
	end
	always @(*) begin
		if (clear) begin
			colour_nxt = 3'b000;
		end
		else if (x == user_x && y == user_y) begin
			colour_nxt = 3'b001;
		end
		else if (x == enemy_x && y == enemy_y) begin
			colour_nxt = 3'b010;
		end
		else if (enem_grid[y*8'd160 + x] == 1'b1) begin
			colour_nxt = 3'b011;
		end
		else if (x % 8'd10 == 8'd0 || y % 7'd10 == 7'd0) begin
			colour_nxt = 3'b100;
		end
		else begin
			colour_nxt = 3'b000;
		end
	end
endmodule

