module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
//----------------------------------------------------------------------------
//   State definitions
//----------------------------------------------------------------------------
localparam standby = 2'b00;
localparam startMeasure = 2'b01;
localparam waitForPulse = 2'b10;
localparam countPulse = 2'b11;
//----------------------------------------------------------------------------
//   Registers
//----------------------------------------------------------------------------
reg [1:0] state = standby;
reg [15:0] timeCount = 0;
reg [15:0] timeoutCounter = 0;
//----------------------------------------------------------------------------
//   Finite State Machine
//----------------------------------------------------------------------------
always @(posedge clk) begin
    if (rst_n == 0) begin
        state <= standby;
        timeCount <= 0;
        sonar_trigger <= 0;
        READY <= 0;
    end
    else begin
        case (state)
            //----------------------------------------------------------------
            //   Standby state - waiting for do_measure input
            //----------------------------------------------------------------
            standby: begin
                sonar_trigger <= 0;
                READY <= 1;
                if (do_measure == 1) begin
                    state <= startMeasure;
                end
            end
            //----------------------------------------------------------------
            //   startMeasure state - generate sonar_trigger pulse
            //----------------------------------------------------------------
            startMeasure: begin
                sonar_trigger <= 1;
                READY <= 0;
                if (sonar_pulse == 1) begin
                    state <= waitForPulse;
                end
            end
            //----------------------------------------------------------------
            //   waitForPulse state - wait for sonar_pulse to go high
            //----------------------------------------------------------------
            waitForPulse: begin
                sonar_trigger <= 0;
                if (sonar_pulse == 0) begin
                    state <= countPulse;
                    timeCount <= 0;
                end
            end
            //----------------------------------------------------------------
            //   countPulse state - count clock cycles until pulse goes low
            //----------------------------------------------------------------
            countPulse: begin
                sonar_trigger <= 0;
                if (sonar_pulse == 0) begin
                    state <= standby;
                    inches <= timeCount / 58;
                end
                else begin
                    timeCount <= timeCount + 1;
                    if (timeoutCounter == 0) begin
                        timeoutCounter <= 1;
                    end
                    else begin
                        timeoutCounter <= timeoutCounter + 1;
                    end
                end
            end
        endcase
    end
end
endmodule

