module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);
  input     clk;
  input     rst;
  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
  reg       s_input_a_ack;
  reg       state;
  reg       [63:0] value;
  assign input_a_ack = s_input_a_ack;
  always @(posedge clk)
  begin
    if(rst)
    begin
      state <= 1'b0;
      s_input_a_ack <= 1'b0;
    end
    else
    begin
      case(state)
      0:
      begin
        s_input_a_ack <= 1'b0;
        if(input_a_stb)
        begin
          value <= input_a;
          state <= 1'b1;
          s_input_a_ack <= 1'b1;
        end
      end
      1:
      begin
        s_input_a_ack <= 1'b0;
        $fopena(32,"resp_z",$s("w"));
        $fdisplay(32,"%0h\n%0h",value[31:0],value[63:32]);
        $fclose(32);
        state <= 1'b0;
      end
      endcase
    end
  end
endmodule

