module named `axis_fork` that is used for forking an AXI4-Stream signal. The module takes in various AXI4-Stream signals such as TVALID, TREADY, TDATA, TLAST, TKEEP, TUSER, and TID, and is parameterized for variable widths for these signals. It uses internal registers to store output data and control signals, and a write enable logic to manage data flow. The module operates on a single clock and reset signal, and the control flow is determined by the clock and reset. Data duplication occurs in the always block when input conditions are met. 
`timescale 1 ns / 1 ns
module axis_fork(
CLK, RESETN,
IV_TVALID, IV_TREADY, IV_TDATA, IV_TLAST, IV_TKEEP, IV_TUSER, IV_TID,
OV0_TVALID, OV0_TREADY, OV0_TDATA, OV0_TLAST, OV0_TKEEP, OV0_TUSER, OV0_TID,
OV1_TVALID, OV1_TREADY, OV1_TDATA, OV1_TLAST, OV1_TKEEP, OV1_TUSER, OV1_TID
);
parameter integer WIDTH_DATA = 8;
parameter integer WIDTH_LAST = 0;
parameter integer WIDTH_KEEP = 0;
parameter integer WIDTH_USER = 0;
parameter integer WIDTH_ID = 0;
input CLK;
input RESETN;
input IV_TVALID;
output IV_TREADY;
input [WIDTH_DATA-1:0] IV_TDATA;
input [WIDTH_LAST-1:0] IV_TLAST;
input [WIDTH_KEEP-1:0] IV_TKEEP;
input [WIDTH_USER-1:0] IV_TUSER;
input [WIDTH_ID-1:0] IV_TID;
output OV0_TVALID;
input OV0_TREADY;
output [WIDTH_DATA-1:0] OV0_TDATA;
output [WIDTH_LAST-1:0] OV0_TLAST;
output [WIDTH_KEEP-1:0] OV0_TKEEP;
output [WIDTH_USER-1:0] OV0_TUSER;
output [WIDTH_ID-1:0] OV0_TID;
output OV1_TVALID;
input OV1_TREADY;
output [WIDTH_DATA-1:0] OV1_TDATA;
output [WIDTH_LAST-1:0] OV1_TLAST;
output [WIDTH_KEEP-1:0] OV1_TKEEP;
output [WIDTH_USER-1:0] OV1_TUSER;
output [WIDTH_ID-1:0] OV1_TID;
reg [WIDTH_DATA-1:0] tdata_0_reg;
reg [WIDTH_LAST-1:0] tlast_0_reg;
reg [WIDTH_KEEP-1:0] tkeep_0_reg;
reg [WIDTH_USER-1:0] tuser_0_reg;
reg [WIDTH_ID-1:0] tid_0_reg;
reg tvalid_0_reg;
reg [WIDTH_DATA-1:0] tdata_1_reg;
reg [WIDTH_LAST-1:0] tlast_1_reg;
reg [WIDTH_KEEP-1:0] tkeep_1_reg;
reg [WIDTH_USER-1:0] tuser_1_reg;
reg [WIDTH_ID-1:0] tid_1_reg;
reg tvalid_1_reg;
reg tready_0_reg;
reg tready_1_reg;
reg we_0_reg;
reg we_1_reg;
assign IV_TREADY = (tready_0_reg & tready_1_reg);
assign OV0_TVALID = tvalid_0_reg;
assign OV0_TDATA = tdata_0_reg;
assign OV0_TLAST = tlast_0_reg;
assign OV0_TKEEP = tkeep_0_reg;
assign OV0_TUSER = tuser_0_reg;
assign OV0_TID = tid_0_reg;
assign OV1_TVALID = tvalid_1_reg;
assign OV1_TDATA = tdata_1_reg;
assign OV1_TLAST = tlast_1_reg;
assign OV1_TKEEP = tkeep_1_reg;
assign OV1_TUSER = tuser_1_reg;
assign OV1_TID = tid_1_reg;
always @(posedge CLK)
begin
  if (RESETN == 1'b0)
  begin
    tvalid_0_reg <= 1'b0;
    tvalid_1_reg <= 1'b0;
    tready_0_reg <= 1'b0;
    tready_1_reg <= 1'b0;
    we_0_reg <= 1'b0;
    we_1_reg <= 1'b0;
  end
  else
  begin
    tready_0_reg <= OV0_TREADY;
    tready_1_reg <= OV1_TREADY;
    if (IV_TVALID & IV_TREADY)
    begin
      tdata_0_reg <= IV_TDATA;
      tlast_0_reg <= IV_TLAST;
      tkeep_0_reg <= IV_TKEEP;
      tuser_0_reg <= IV_TUSER;
      tid_0_reg <= IV_TID;
      tvalid_0_reg <= 1'b1;
      we_0_reg <= 1'b1;
    end
    else
    begin
      we_0_reg <= 1'b0;
    end
    if (IV_TVALID & ~(we_0_reg))
    begin
      tdata_1_reg <= IV_TDATA;
      tlast_1_reg <= IV_TLAST;
      tkeep_1_reg <= IV_TKEEP;
      tuser_1_reg <= IV_TUSER;
      tid_1_reg <= IV_TID;
      tvalid_1_reg <= 1'b1;
      we_1_reg <= 1'b1;
    end
    else
    begin
      we_1_reg <= 1'b0;
    end
    if (we_0_reg & ~(we_1_reg))
    begin
      tvalid_1_reg <= 1'b0;
    end
    if (we_1_reg & ~(we_0_reg))
    begin
      tvalid_0_reg <= 1'b0;
    end
  end
end
endmodule

