module has features for handling simultaneous read operations, write bypassing, and overflow control during writes. It operates with an asynchronous reset and uses the negative clock edge for write operations. The register file is reset to zero on reset and provides two read ports and one write port. The design uses combinational logic for read operations and sequential logic for writes.
`timescale 1ns/1ps
module registers(clk,read1,read2,data1,data2,regwrite,wrreg,wrdata,rst,of_control);
	input clk,rst;
	input [1:0]of_control;
	input [4:0]	read1, read2;
	output [31:0]	data1, data2;
	input regwrite;
	input [4:0]wrreg;
	input [31:0]wrdata;
	reg [31:0] regs [31:0];
	reg [31:0] data1_tmp,data2_tmp;
	assign data1 = data1_tmp;
	assign data2 = data2_tmp;
	integer i;
	always @(read1 or read2 or rst)
	begin
		if(rst)
		begin
			data1_tmp <= 32'b0;
			data2_tmp <= 32'b0;
		end
		else
		begin
			if(read1 == 5'b0)
				data1_tmp <= 32'b0;
			else if(read1 == wrreg)
			begin
				if(regwrite && of_control == 2'b00)
					data1_tmp <= wrdata;
				else if(regwrite && of_control == 2'b01)
					data1_tmp <= wrdata;
				else if(regwrite && of_control == 2'b10)
					data1_tmp <= wrdata;
				else
					data1_tmp <= regs[read1];
			end
			else
				data1_tmp <= regs[read1];
			if(read2 == 5'b0)
				data2_tmp <= 32'b0;
			else if(read2 == wrreg)
			begin
				if(regwrite && of_control == 2'b00)
					data2_tmp <= wrdata;
				else if(regwrite && of_control == 2'b01)
					data2_tmp <= wrdata;
				else if(regwrite && of_control == 2'b10)
					data2_tmp <= wrdata;
				else
					data2_tmp <= regs[read2];
			end
			else
				data2_tmp <= regs[read2];
		end
	end
	always @(negedge clk or rst)
	begin
		if(rst)
		begin
			for(i = 0; i < 32; i = i + 1)
				regs[i] <= 32'b0;
		end
		else
		begin
			if(regwrite)
			begin
				if(of_control == 2'b00)
					regs[wrreg] <= wrdata;
				else if(of_control == 2'b01)
					regs[wrreg] <= wrdata;
				else if(of_control == 2'b10)
					regs[wrreg] <= wrdata;
			end
		end
