module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
    localparam TOTAL_COLS = 10'd800;
    localparam TOTAL_ROWS = 10'd525;
    localparam ACTIVE_COLS = 10'd640;
    localparam ACTIVE_ROWS = 10'd480;
    reg [9:0] col_count = 0;
    reg [9:0] row_count = 0;
    reg hsync = 1'b1;
    reg vsync = 1'b1;
    always @(posedge i_clk) begin
        if(col_count == TOTAL_COLS-1) begin
            col_count <= 0;
            if(row_count == TOTAL_ROWS-1) begin
                row_count <= 0;
            end else begin
                row_count <= row_count + 1;
            end
        end else begin
            col_count <= col_count + 1;
        end
        if(col_count == TOTAL_COLS-ACTIVE_COLS) begin
            hsync <= 1'b0;
        end else if(col_count == TOTAL_COLS-1) begin
            hsync <= 1'b1;
        end
        if(row_count == TOTAL_ROWS-ACTIVE_ROWS) begin
            vsync <= 1'b0;
        end else if(row_count == TOTAL_ROWS-1) begin
            vsync <= 1'b1;
        end
    end
    always @(posedge i_clk) begin
        o_col_count <= col_count;
        o_row_count <= row_count;
    end
    assign o_hsync = hsync;
    assign o_vsync = vsync;
endmodule

