module db (
        input clk, n_reset, button_in,
        output reg out
    );
    parameter maxbit = 3;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_reset, q_add;
    wire out_next;
    always @(*) begin
        q_next = q_reg + 1'b1;
    end
    assign q_reset = (f1 ^ f2);
    assign q_add = ~(q_reset | q_reg[maxbit-1]);
    assign out_next = (q_reg[maxbit-1:0] == {maxbit{1'b1}});
    always @(posedge clk, negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
            out <= 0;
        end else begin
            if (q_reset) begin
                f1 <= button_in;
                f2 <= f1;
            end else if (q_add) begin
                q_reg <= q_next;
            end
            out <= out_next;
        end
    end
endmodule

