module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
    reg [7 : 0] mem [0 : 15];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    reg [7 : 0] q_temp;
    always @(posedge clock) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end
        else begin
            if (wrreq) begin
                mem[wp] <= data;
                if (wp == 15) begin
                    wp <= 0;
                    w_flag <= ~w_flag;
                end
                else
                    wp <= wp + 1;
            end
            if (rdreq) begin
                q_temp <= mem[rp];
                if (rp == 15) begin
                    rp <= 0;
                    r_flag <= ~r_flag;
                end
                else
                    rp <= rp + 1;
            end
        end
    end
    always @(*) begin
        if (wp == rp && w_flag != r_flag) begin
            full <= 1;
            empty <= 0;
        end
        else if (wp == rp && w_flag == r_flag) begin
            full <= 0;
            empty <= 1;
        end
        else begin
            full <= 0;
            empty <= 0;
        end
    end
    assign q = q_temp;
endmodule

