module conv_apb 
  (
    input wire PCLK,           
    input wire PRESETB,        
    input wire [31:0] PADDR,   
    input wire PSEL,           
    input wire PENABLE,        
    input wire PWRITE,         
    input wire [31:0] PWDATA,  
    output wire [31:0] PRDATA,
    input wire [31:0] clk_counter,
    input wire conv_done,
    output reg conv_start,
    output reg [2:0]  COMMAND,
    output reg [8:0]  InCh,
    output reg [8:0]  OutCh,
    output reg [5:0]  FLength,
    input wire  F_writedone,
    output reg  F_writedone_respond,
    input wire  B_writedone,
    output reg  B_writedone_respond,
    input wire  rdy_to_transmit,
    output reg  rdy_to_transmit_respond,
    input wire  transmit_done,
    output reg  transmit_done_respond 
  );
  reg [31:0] prdata_temp;
  reg [31:0] paddr_temp;
  reg pwrite_temp;
  reg penable_temp;
  reg psel_temp;
  reg [31:0] clk_counter_temp;
  reg conv_done_temp;
  always @(posedge PCLK or negedge PRESETB) begin
    if (PRESETB == 1'b0) begin
      paddr_temp <= 32'b0;
      pwrite_temp <= 1'b0;
      penable_temp <= 1'b0;
      psel_temp <= 1'b0;
      clk_counter_temp <= 32'b0;
      conv_done_temp <= 1'b0;
    end else begin
      paddr_temp <= PADDR;
      pwrite_temp <= PWRITE;
      penable_temp <= PENABLE;
      psel_temp <= PSEL;
      clk_counter_temp <= clk_counter;
      conv_done_temp <= conv_done;
    end
  end
  always @(posedge PCLK or negedge PRESETB) begin
    if (PRESETB == 1'b0) begin
      prdata_temp <= 32'b0;
    end else begin
      if (psel_temp && penable_temp && pwrite_temp) begin
        case (paddr_temp[3:0])
          4'h0: begin
            conv_start <= PWDATA[0];
            COMMAND <= PWDATA[3:1];
          end
          4'h4: begin
            InCh <= PWDATA[8:0];
          end
          4'h8: begin
            OutCh <= PWDATA[8:0];
          end
          4'hc: begin
            FLength <= PWDATA[5:0];
          end
        endcase
      end
    end
  end
  always @(posedge PCLK or negedge PRESETB) begin
    if (PRESETB == 1'b0) begin
      F_writedone_respond <= 1'b0;
      B_writedone_respond <= 1'b0;
      rdy_to_transmit_respond <= 1'b0;
      transmit_done_respond <= 1'b0;
    end else begin
      if (psel_temp && penable_temp && pwrite_temp) begin
        case (paddr_temp[3:0])
          4'h0: begin
            F_writedone_respond <= PWDATA[0];
            B_writedone_respond <= PWDATA[1];
            rdy_to_transmit_respond <= PWDATA[2];
            transmit_done_respond <= PWDATA[3];
          end
        endcase
      end
    end
  end
  always @(*) begin
    if (psel_temp && !penable_temp && !pwrite_temp) begin
      case (paddr_temp[3:0])
        4'h0: begin
          prdata_temp <= {29'b0, conv_start, COMMAND};
        end
        4'h4: begin
          prdata_temp <= {23'b0, InCh};
        end
        4'h8: begin
          prdata_temp <= {23'b0, OutCh};
        end
        4'hc: begin
          prdata_temp <= {26'b0, FLength};
        end
        4'h10: begin
          prdata_temp <= {31'b0, F_writedone};
        end
        4'h14: begin
          prdata_temp <= {31'b0, B_writedone};
        end
        4'h18: begin
          prdata_temp <= {31'b0, rdy_to_transmit};
        end
        4'h1c: begin
          prdata_temp <= {31'b0, transmit_done};
        end
        4'h20: begin
          prdata_temp <= clk_counter_temp;
        end
        4'h24: begin
          prdata_temp <= {31'b0, conv_done_temp};
        end
      endcase
    end else begin
      prdata_temp <= 32'b0;
    end
  end
  assign PRDATA = prdata_temp;
endmodule

