module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
    // Internal registers
    reg [7:0] shift_reg;
    reg [3:0] count;
    // Sequential logic for shift register and counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset condition
            shift_reg <= 8'b0;
            count <= 4'b0;
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
        end else begin
            if (din_valid) begin
                // Shift in the serial data into the MSB of the shift register
                shift_reg <= (shift_reg << 1) | din_serial;
                // Increment the count
                count <= count + 1;
                // Reset the valid output
                dout_valid <= 1'b0;
                if (count == 4'd7) begin
                    // If 8 valid bits have been received, shift out a byte
                    dout_parallel <= shift_reg;
                    dout_valid <= 1'b1;
                    // Reset the shift register for the next byte
                    shift_reg <= 8'b0;
                    // Keep the count at 8 to prevent accidental output
                    // count <= 4'b0;
                end
            end else begin
                // If din_valid is not high, do not shift in new data
                // and reset the valid output
                dout_valid <= 1'b0;
            end
        end
    end
endmodule

