`timescale 1 ns / 1 ns
module rca_16b(A, B, S, C_out);
    input [N-1: 0] A, B;
    output [N-1:0] S;
    output         C_out;
    parameter N = 16;
    wire [N-1:0] C;
    genvar i;
    generate
        for (i = 0; i <= N-1; i = i + 1)
        begin: rca_16b_loop
            if (i == 0)
            begin
                assign S[i] = A[i] ^ B[i];
                assign C[i] = A[i] & B[i];
            end
            else
            begin
                assign S[i] = A[i] ^ B[i] ^ C[i-1];
                assign C[i] = (A[i] & B[i]) | (A[i] & C[i-1]) | (B[i] & C[i-1]);
            end
        end
    endgenerate
    assign C_out = C[N-1];
endmodule

