module FSM_game(
input wire iRST,
input wire iCLK,
input wire [1:0] iA,
input wire [1:0] iB,
output wire oA,
output wire oB
);
//declare the internal signals
reg [2:0] sSTATE;
reg [2:0] sNEXT_STATE;
reg [1:0] sWIN;
//declare the state parameters
parameter DRAW = 3'b000;
parameter B_LEAD = 3'b001;
parameter B_WIN = 3'b010;
parameter A_LEAD = 3'b011;
parameter A_WIN = 3'b100;
//declare the outputs
assign oA = sWIN[1];
assign oB = sWIN[0];
//FSM
//state register
always @(posedge iCLK or posedge iRST)
begin
	if(iRST)
		sSTATE <= DRAW;
	else
		sSTATE <= sNEXT_STATE;
end
//next state logic
always @(sSTATE or iA or iB)
begin
	case(sSTATE)
		DRAW:
			if(iA == 2'b01 && iB == 2'b00)
				sNEXT_STATE <= B_LEAD;
			else if(iA == 2'b00 && iB == 2'b01)
				sNEXT_STATE <= A_LEAD;
			else
				sNEXT_STATE <= DRAW;
		B_LEAD:
			if(iA == 2'b00 && iB == 2'b01)
				sNEXT_STATE <= A_LEAD;
			else if(iA == 2'b01 && iB == 2'b00)
				sNEXT_STATE <= B_LEAD;
			else if(iA == 2'b10 && iB == 2'b00)
				sNEXT_STATE <= B_WIN;
			else if(iA == 2'b00 && iB == 2'b10)
				sNEXT_STATE <= A_WIN;
			else
				sNEXT_STATE <= B_LEAD;
		B_WIN:
			sNEXT_STATE <= B_WIN;
		A_LEAD:
			if(iA == 2'b01 && iB == 2'b00)
				sNEXT_STATE <= B_LEAD;
			else if(iA == 2'b00 && iB == 2'b01)
				sNEXT_STATE <= A_LEAD;
			else if(iA == 2'b00 && iB == 2'b10)
				sNEXT_STATE <= A_WIN;
			else if(iA == 2'b10 && iB == 2'b00)
				sNEXT_STATE <= B_WIN;
			else
				sNEXT_STATE <= A_LEAD;
		A_WIN:
			sNEXT_STATE <= A_WIN;
		default:
			sNEXT_STATE <= DRAW;
	endcase
end
//output logic
always @(sSTATE)
begin
	case(sSTATE)
		DRAW:
			sWIN <= 2'b00;
		B_LEAD:
			sWIN <= 2'b00;
		B_WIN:
			sWIN <= 2'b11;
		A_LEAD:
			sWIN <= 2'b00;
		A_WIN:
			sWIN <= 2'b00;
		default:
			sWIN <= 2'b00;
	endcase
end
endmodule

