module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
);
//------------------------------------------------------------------------------
// Registers
reg [4:0] bit;       // bit being tested (0 thru 30)
reg [31:0] part;     // remaining part of x
reg [15:0] result;   // result being constructed
//------------------------------------------------------------------------------
// Bit values
wire [31:0] bitv = 1 << bit;
wire [15:0] partv = part[15:0];
//------------------------------------------------------------------------------
// Compare and subtract
wire [15:0] sub = partv - bitv;
wire ok = sub[15] == 0;
//------------------------------------------------------------------------------
// Process the next bit
always @(*)
begin
    // done?
    if (bit == 0)
    begin
        y = result[15:0];
    end
    // not done yet...
    else
    begin
        // ok, so what's the result so far?
        if (ok)
        begin
            // subtract and shift
            part = part << 2 | sub << bit - 16;
            result = result | bitv;
        end
        else
        begin
            // nope, so just shift
            part = part << 2;
        end
        // and on to the next bit
        bit = bit - 1;
    end
end
//------------------------------------------------------------------------------
endmodule

