module SCK_control_slave( input wire SCK_in, input wire CPOL, input wire CPHA, input wire idle, output reg S_BaudRate, output wire Shift_clk, output wire Sample_clk );
  reg  Delay_out1;
  wire Logical_Operator_out1;
  wire Logical_Operator1_out1;
  wire Switch_out1;
  wire Switch1_out1;
  wire AND_out1;
  wire AND1_out1;
  // <S1>/Delay
  always @(posedge SCK_in)
    Delay_out1 <= idle;
  assign Logical_Operator_out1 =  ~ Delay_out1;
  assign Logical_Operator1_out1 =  ~ S_BaudRate;
  assign Switch_out1 = (idle == 1'b0 ? Logical_Operator_out1 :
              S_BaudRate);
  assign Switch1_out1 = (idle == 1'b0 ? Logical_Operator1_out1 :
              Switch_out1);
  // <S1>/AND
  assign AND_out1 = Switch1_out1 & SCK_in;
  // <S1>/AND1
  assign AND1_out1 = Logical_Operator_out1 & SCK_in;
  assign Shift_clk = AND_out1;
  assign Sample_clk = AND1_out1;
  always @(CPOL, CPHA, idle) begin
    // <S1>/S_BaudRate
    case ({CPOL, CPHA})
      2'b00: S_BaudRate =  ~ idle;
      2'b01: S_BaudRate = idle;
      2'b10: S_BaudRate =  ~ idle;
      2'b11: S_BaudRate = idle;
      default: S_BaudRate = idle;
    endcase
  end
endmodule

