module implements a combinational design, reacting to input changes
// immediately.
//
// The module handles all possible 4-bit hex inputs, and provides a default
// pattern for invalid inputs.
//
// The seg output is updated whenever blank or hex changes, so that the
// display reflects the current inputs immediately.
module hex_7seg(
input wire blank,
input wire [3:0] hex,
output reg [6:0] seg
);
// combinational always block
always @(*) begin
  if (blank) begin
    seg = 7'b1111111;
  end else begin
    case (hex)
      4'h0: seg = 7'b1000000;
      4'h1: seg = 7'b1111001;
      4'h2: seg = 7'b0100100;
      4'h3: seg = 7'b0110000;
      4'h4: seg = 7'b0011001;
      4'h5: seg = 7'b0010010;
      4'h6: seg = 7'b0000010;
      4'h7: seg = 7'b1111000;
      4'h8: seg = 7'b0000000;
      4'h9: seg = 7'b0010000;
      4'hA: seg = 7'b0001000;
      4'hB: seg = 7'b0000011;
      4'hC: seg = 7'b1000110;
      4'hD: seg = 7'b0100001;
      4'hE: seg = 7'b0000110;
      4'hF: seg = 7'b0001110;
      default: seg = 7'b1001001;
    endcase
  end
end
endmodule

