module rx_tb;
    parameter ref_clk_period = 10;
    parameter baud = 115200;
    parameter baud_period = 1000000000/baud;
    parameter ref_clk_per_baud = ref_clk_period/baud_period;
    parameter num_samples = 100;
    reg ref_clk = 0;
    reg baud_clk = 0;
    reg [15:0] ref_clk_counter = 0;
    reg [15:0] baud_counter = 0;
    reg [7:0] sample_counter = 0;
    reg [9:0] samples [0:num_samples-1];
    reg [9:0] cur_sample = 0;
    reg [3:0] bit_counter = 0;
    reg [3:0] ser_in = 0;
    reg reset = 1;
    wire [7:0] par_out;
    wire Rx_valid;
    wire err_par;
    wire err_stop;
    always begin
        #(ref_clk_period);
        ref_clk = ~ref_clk;
    end
    always @(posedge ref_clk) begin
        if (reset) begin
            ref_clk_counter <= 0;
            baud_clk <= 0;
        end
        else begin
            if (ref_clk_counter == ref_clk_per_baud) begin
                ref_clk_counter <= 0;
                baud_clk <= ~baud_clk;
            end
            else begin
                ref_clk_counter <= ref_clk_counter + 1;
            end
        end
    end
    always @(posedge baud_clk) begin
        if (reset) begin
            bit_counter <= 0;
            sample_counter <= 0;
            $readmemh("samples.mem", samples);
        end
        else begin
            if (bit_counter == 10) begin
                bit_counter <= 0;
                sample_counter <= sample_counter + 1;
                if (sample_counter == num_samples) begin
                    $finish;
                end
                cur_sample <= samples[sample_counter];
            end
            else begin
                bit_counter <= bit_counter + 1;
                ser_in <= {ser_in[2:0], cur_sample[bit_counter]};
            end
        end
    end
    always @(negedge baud_clk) begin
        if (reset) begin
            reset <= 0;
        end
    end
    UART_Rx UART_Rx(
        .ser_in(ser_in),
        .clk(baud_clk),
        .reset(reset),
        .par_out(par_out),
        .Rx_valid(Rx_valid),
        .err_par(err_par),
        .err_stop(err_stop)
    );
endmodule
module UART_Rx(
    input ser_in,
    input clk,
    input reset,
    output reg [7:0] par_out,
    output reg Rx_valid,
    output reg err_par,
    output reg err_stop
);
    parameter ref_clk_period = 10;
    parameter baud = 115200;
    parameter baud_period = 1000000000/baud;
    parameter ref_clk_per_baud = ref_clk_period/baud_period;
    parameter idle = 2'b00;
    parameter start = 2'b01;
    parameter data = 2'b10;
    parameter stop = 2'b11;
    reg [1:0] state = idle;
    reg [3:0] bit_counter = 0;
    reg [7:0] par_out_reg = 0;
    reg [7:0] ref_clk_counter = 0;
    reg [7:0] baud_counter = 0;
    reg [7:0] par_out_buffer = 0;
    reg Rx_valid = 0;
    reg err_par = 0;
    reg err_stop = 0;
    always @(posedge clk) begin
        if (reset) begin
            state <= idle;
            ref_clk_counter <= 0;
            baud_counter <= 0;
            bit_counter <= 0;
            Rx_valid <= 0;
            err_par <= 0;
            err_stop <= 0;
        end
        else begin
            if (ref_clk_counter == ref_clk_per_baud) begin
                ref_clk_counter <= 0;
                baud_counter <= baud_counter + 1;
            end
            else begin
                ref_clk_counter <= ref_clk_counter + 1;
            end
            if (baud_counter == 8) begin
                baud_counter <= 0;
                case (state)
                    idle: begin
                        if (ser_in == 0) begin
                            state <= start;
                            bit_counter <= 0;
                        end
                    end
                    start: begin
                        if (bit_counter == 4'd7) begin
                            state <= data;
                            bit_counter <= 0;
                        end
                        else begin
                            bit_counter <= bit_counter + 1;
                        end
                    end
                    data: begin
                        if (bit_counter == 4'd7) begin
                            bit_counter <= 0;
                            if (baud_counter == 4'd7) begin
                                par_out_reg <= {ser_in, par_out_reg[7:1]};
                                if (bit_counter == 4'd9) begin
                                    state <= stop;
                                end
                                else begin
                                    bit_counter <= bit_counter + 1;
                                end
                            end
                        end
                        else begin
                            bit_counter <= bit_counter + 1;
                        end
                    end
                    stop: begin
                        if (bit_counter == 4'd7) begin
                            state <= idle;
                            Rx_valid <= 1;
                            par_out_buffer <= par_out_reg;
                        end
                        else begin
                            bit_counter <= bit_counter + 1;
                        end
                    end
                endcase
            end
        end
    end
    always @(negedge clk) begin
        if (Rx_valid) begin
            par_out <= par_out_buffer;
            Rx_valid <= 0;
            err_par <= par_out_buffer[0] ^^^^ par_out_buffer[1] ^^^^ par_out_buffer[2] ^^^^ par_out_buffer[3] ^^^^ par_out_buffer[4] ^^^^ par_out_buffer[5] ^^^^ par_out_buffer[6] ^^^^ par_out_buffer[7];
            err_stop <= ser_in;
        end
    end
endmodule

