module pcm(set,clk,q1,q2,q3);
	input set,clk;
	output q1,q2,q3;
	reg [4:0] count;
	always @(posedge clk)
	begin
		if(set==1)
			count<=9;
		else
		begin
			if(count>0)
				count<=count-1;
		end
	end
	reg q1r,q2r,q3r;
	always @(count)
	begin
		if(count>=7)
		begin
			q1r<=1;
			q2r<=0;
			q3r<=0;
		end
		else if(count>=4)
		begin
			q1r<=0;
			q2r<=1;
			q3r<=0;
		end
		else if(count>=1)
		begin
			q1r<=0;
			q2r<=0;
			q3r<=1;
		end
		else
		begin
			q1r<=0;
			q2r<=0;
			q3r<=0;
		end
	end
	assign q1=q1r;
	assign q2=q2r;
	assign q3=q3r;
endmodule

