module ControlUnit(input[5:0] opcode,
		input[5:0] funct,
		output reg reg_dst,
		output reg reg_write,
		output reg[1:0] alu_src,
		output reg[3:0] alu_op,
		output reg branch,
		output reg mem_write,
		output reg mem_to_reg,
        	output reg zero_sign_ext,
		output reg mult_op,
		output reg mfhi,
		output reg mflo);
	always @(*) begin
		//Default values
		reg_dst = 1'b0;
		reg_write = 1'b0;
		alu_src = 2'b00;
		alu_op = 4'b0000;
		branch = 1'b0;
		mem_write = 1'b0;
		mem_to_reg = 1'b0;
		zero_sign_ext = 1'b0;
		mult_op = 1'b0;
		mfhi = 1'b0;
		mflo = 1'b0;
		//R-type instructions
		if (opcode == 6'b000000) begin
			reg_dst = 1'b1;
			reg_write = 1'b1;
			alu_src = 2'b00;
			alu_op = 4'b0000;
			branch = 1'b0;
			mem_write = 1'b0;
			mem_to_reg = 1'b0;
			zero_sign_ext = 1'b0;
			mult_op = 1'b0;
			mfhi = 1'b0;
			mflo = 1'b0;
			//R-type instructions with special operations
			if (funct == 6'b011001) begin //mult
				mult_op = 1'b1;
			end
			if (funct == 6'b011010) begin //div
				mult_op = 1'b1;
			end
			if (funct == 6'b010000) begin //mfhi
				mfhi = 1'b1;
			end
			if (funct == 6'b010010) begin //mflo
				mflo = 1'b1;
			end
		end
		//I-type instructions
		else begin
			reg_dst = 1'b0;
			reg_write = 1'b1;
			alu_src = 2'b00;
			alu_op = 4'b0000;
			branch = 1'b0;
			mem_write = 1'b0;
			mem_to_reg = 1'b0;
			zero_sign_ext = 1'b0;
			mult_op = 1'b0;
			mfhi = 1'b0;
			mflo = 1'b0;
			//lw
			if (opcode == 6'b100011) begin
				alu_src = 2'b01;
				alu_op = 4'b0000;
				mem_to_reg = 1'b1;
			end
			//sw
			if (opcode == 6'b101011) begin
				alu_src = 2'b01;
				alu_op = 4'b0000;
				mem_write = 1'b1;
			end
			//beq
			if (opcode == 6'b000100) begin
				alu_src = 2'b00;
				alu_op = 4'b0001;
				branch = 1'b1;
			end
		end
	end
endmodule

module that implements the BranchLogic. The module takes the zero (zf), carry (cf), and negative (nf) flags and a select line to determine which flag to use for the branch decision. It also takes a branch control line. The module then determines whether the branch should be taken and updates the flag register accordingly. 
`timescale 1ns / 1ps
module BranchLogic (zf,cf,nf,sel,branch,branch_out,flag_reg);
input zf,cf,nf,branch;
input [1:0]sel;
output branch_out;
output [2:0] flag_reg;
wire flag;
assign flag = (sel[1]) ? nf : (sel[0] ? cf : zf);
assign branch_out = flag & branch;
assign flag_reg = (branch) ? {sel,flag} : 3'b000;
endmodule

