module bus_mux (din,sel,dout);
parameter DAT_WIDTH = 32;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = DAT_WIDTH * SEL_WIDTH;
input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
genvar i,j;
generate
	for (i = 0; i < SEL_WIDTH; i = i + 1) begin : gen_mux
		for (j = 0; j < DAT_WIDTH; j = j + 1) begin : gen_temp
			wire [DAT_WIDTH-1:0] temp;
			assign temp[j] = din[i*DAT_WIDTH+j];
		end
		assign dout = gen_mux[i].gen_temp[sel[i]].temp;
	end
endgenerate
endmodule

