module that takes a clock signal as input and divides it by a given divisor to produce an output clock signal. The divisor is specified as a parameter, and the counter that performs the division is designed to be as large as possible while still allowing a reasonable range of divisor values without overflow. The module is designed to be synthesizable and should work on most FPGA and ASIC development platforms.
`timescale 1ns / 1ps
module clock_divider(clock_in,clock_out
    );
input clock_in; 
output reg clock_out;
localparam WIDTH = 28;
localparam DIVISOR = 28'd100000000;
reg[WIDTH-1:0] counter = 0;
always @(posedge clock_in)
begin
	counter <= counter + 1;
	if(counter >= (DIVISOR-1))
		counter <= 0;
	clock_out <= (counter < DIVISOR/2) ? 1'b1 : 1'b0;
end
endmodule

module, led_wave, is designed to generate a wave pattern on an 8-bit LED output. It uses a counter of length CTR_LEN (default value of 25) to increment its value on every clock cycle. The LED pattern is then updated based on the counter's current value. The module is synthesizable Verilog code that matches the given specification and module interface. 
`timescale 1ns / 1ps
module led_wave #(parameter CTR_LEN = 25)(
	input wire clk,
	input wire rst,
	output reg[7:0] led
   );
reg [7:0] led_reg;
reg [CTR_LEN-1:0] ctr_d, ctr_q;
reg [2:0] i, j;
reg [3:0] k;
reg cmp;
always @(ctr_q) begin
	ctr_d = ctr_q + 1'b1;
	led_reg = 8'b0;
	for (i = 0; i < 8; i = i + 1) begin
		if (ctr_q[CTR_LEN-1 - i]) begin
			cmp = 1'b1;
		end else begin
			cmp = 1'b0;
		end
		for (j = 0; j < 3; j = j + 1) begin
			if (i - j >= 0) begin
				if (cmp) begin
					if (ctr_q[CTR_LEN-1 - i + j]) begin
						cmp = 1'b1;
					end else begin
						cmp = 1'b0;
					end
				end else begin
					if (~ctr_q[CTR_LEN-1 - i + j]) begin
						cmp = 1'b1;
					end else begin
						cmp = 1'b0;
					end
				end
			end
		end
		if (cmp) begin
			for (k = 0; k < 4; k = k + 1) begin
				if (i - k >= 0) begin
					led_reg[i - k] = cmp;
				end
			end
		end
	end
	led = led_reg;
end
always @(posedge clk) begin
	if (rst) begin
		ctr_q <= {CTR_LEN{1'b0}};
	end else begin
		ctr_q <= ctr_d;
	end
end
endmodule

