module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
  wire [counterSize-1:0] counts [numOfCounters-1:0];
  wire [numOfCounters-1:0] terminalCounts;
  wire [numOfCounters-1:0] enables;
  assign enables[0] = 1'b1;
  assign outCount = counts[numOfCounters-1];
  genvar i;
  generate
    for (i = 0; i < numOfCounters; i = i + 1) begin : NBitCounterChain_loop
      NBitCounter_1 counter (
        .clk(clk),
        .reset(reset),
        .enable(enables[i]),
        .count(counts[i]),
        .terminalCount(terminalCounts[i]));
      assign enables[i+1] = terminalCounts[i];
    end
  endgenerate
endmodule
module NBitCounter_1 (
   input  wire                   clk,
   input  wire                   reset,
   input  wire                   enable,
   output wire [15:0]            count,
   output wire                   terminalCount
);
  reg [15:0] count_reg = 16'b0000000000000000;
  wire [15:0] count_next = count_reg + 16'b0000000000000001;
  always @(posedge clk) begin
    if (reset) begin
      count_reg <= 16'b0000000000000000;
    end else if (enable) begin
      count_reg <= count_next;
    end
  end
  assign count = count_reg;
  assign terminalCount = count_reg == 16'b1111111111111111;
endmodule

