module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
);
parameter H_DISPLAY = 640;
parameter H_FRONT = 16;
parameter H_BACK = 48;
parameter H_RETRACE = 96;
parameter V_DISPLAY = 480;
parameter V_FRONT = 10;
parameter V_BACK = 33;
parameter V_RETRACE = 2;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
always @(posedge clk)
  if (rst)
    h_count_reg <= 10'b0000000000;
  else if (h_count_reg == (H_DISPLAY + H_FRONT + H_BACK + H_RETRACE - 1))
    h_count_reg <= 10'b0000000000;
  else
    h_count_reg <= h_count_reg + 10'b0000000001;
always @(posedge clk)
  if (rst)
    v_count_reg <= 10'b0000000000;
  else if (h_count_reg == (H_DISPLAY + H_FRONT + H_BACK + H_RETRACE - 1))
    if (v_count_reg == (V_DISPLAY + V_FRONT + V_BACK + V_RETRACE - 1))
      v_count_reg <= 10'b0000000000;
    else
      v_count_reg <= v_count_reg + 10'b0000000001;
always @(posedge clk)
  if (rst)
    active <= 1'b0;
  else
    active <= (h_count_reg < H_DISPLAY) && (v_count_reg < V_DISPLAY);
always @(posedge clk)
  if (rst)
    hsync <= 1'b0;
  else
    hsync <= !((h_count_reg >= (H_DISPLAY + H_FRONT)) && (h_count_reg <= (H_DISPLAY + H_FRONT + H_RETRACE - 1)));
always @(posedge clk)
  if (rst)
    vsync <= 1'b0;
  else
    vsync <= !((v_count_reg >= (V_DISPLAY + V_FRONT)) && (v_count_reg <= (V_DISPLAY + V_FRONT + V_RETRACE - 1)));
assign xaddr = h_count_reg;
assign yaddr = v_count_reg;
endmodule

