module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );
    // Register to hold the current state of the shift register
    reg [WIDTH-1:0] shift_reg;
    // Wire to hold the feedback bit
    wire feedback_bit;
    // Compute the feedback bit using the taps configuration
    assign feedback_bit = ^{ (shift_reg & TAPS) };
    // Control logic implements a Mealy state machine with a single clock cycle
    always @(posedge clk_i) begin
        if (rst_i == 1'b1) begin
            // Reset the register to the seed value
            shift_reg <= SEED;
        end else if (next_i == 1'b1) begin
            // When enabled, shift the register and add the feedback bit
            shift_reg <= {shift_reg[WIDTH-2:0], feedback_bit};
        end
    end
    // Assign the output to the current state of the register
    assign output_o = shift_reg;
endmodule

