module TopModule (
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
) ;
    reg [15:0] q_reg, q_next;
    reg [2:0] ena_reg, ena_next;
    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 16'b0;
            ena_reg <= 3'b0;
        end
        else begin
            q_reg <= q_next;
            ena_reg <= ena_next;
        end
    end
    always @(*) begin
        q_next = q_reg;
        ena_next = 3'b0;
        q_next[3:0] = q_reg[3:0] + 1'b1;
        if (q_reg[3:0] == 4'd9) begin
            q_next[3:0] = 4'b0;
            q_next[7:4] = q_reg[7:4] + 1'b1;
            if (q_reg[7:4] == 4'd9) begin
                q_next[7:4] = 4'b0;
                q_next[11:8] = q_reg[11:8] + 1'b1;
                if (q_reg[11:8] == 4'd9) begin
                    q_next[11:8] = 4'b0;
                    q_next[15:12] = q_reg[15:12] + 1'b1;
                    if (q_reg[15:12] == 4'd9) begin
                        q_next[15:12] = 4'b0;
                        ena_next[0] = 1'b1;
                    end
                end
            end
        end
        ena_next[1] = q_reg[3:0] == 4'd9 && q_reg[7:4] == 4'd9;
        ena_next[2] = q_reg[3:0] == 4'd9 && q_reg[7:4] == 4'd9 && q_reg[11:8] == 4'd9;
    end
    assign ena = ena_reg;
    assign q = q_reg;
endmodule

module TopModule(
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
) ;
  // Minimum sum-of-products form of the output.
  assign out_sop = (~d & ~c & ~b & a) | (~d & c & ~b & ~a) | (d & ~c & b & ~a) | (d & c & ~b & a) | (d & ~c & ~b & ~a) | (d & c & b & a) ;
  // Minimum product-of-sums form of the output.
  assign out_pos = (a | b | c | d) & (~a | ~b | c | d) & (~a | b | ~c | d) & (a | ~b | ~c | d) & (~a | ~b | ~c | ~d) & (a | b | ~c | ~d) ;
endmodule

