module TopModule (
    input in,
    input [3:0] state,
    output [3:0] next_state,
    output out
) ;
  // state transition logic: next_state = f(state, in)
  assign next_state[0] = state[0] & ~in | state[1] & ~in | state[2] & ~in;
  assign next_state[1] = state[0] &  in | state[2] &  in | state[3] &  in;
  assign next_state[2] = state[1] &  in | state[3] &  in | state[0] &  in;
  assign next_state[3] = state[2] & ~in | state[3] & ~in;
  // output logic:  out = f(state, in) for a moore machine
  assign out = state[3];
endmodule

