module TopModule(
    input  clk,
    input  areset,
    input  x,
    output z
) ;
    parameter A = 2'b01, B = 2'b10 ;
    reg [1:0] state, next_state ;
    // Asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= A ;
        else
            state <= next_state ;
    end
    // Synchronous reset
    // always @(posedge clk) begin
    //     if (areset)
    //         state <= A ;
    //     else
    //         state <= next_state ;
    // end
    // Combinational logic
    always @(*) begin
        case (state)
            A : next_state = x ? B : A ;
            B : next_state = x ? B : B ;
        endcase
    end
    // Output logic
    assign z = (state == B) ;
endmodule

