module TopModule (
    input c,
    input d,
    output [3:0] mux_in
) ;
    // I'm not sure if this is synthesizable, but it looks like it:
    //
    //      ab
    //  cd  00  01  11  10
    //  00 | 0 | 0 | 0 | 1 |
    //  01 | 1 | 0 | 0 | 0 |
    //  11 | 1 | 0 | 1 | 1 |
    //  10 | 1 | 0 | 0 | 1 |
    //
    // The truth table can be found by looking at the simulation waveforms.
    //
    // It would be nice to be able to do something like this:
    //
    //   assign mux_in[0] = ~c & ~d;
    //   assign mux_in[1] = ~c &  d;
    //   assign mux_in[2] =  c & ~d;
    //   assign mux_in[3] =  c &  d;
    //
    // But we can't.  The synthesized circuit has a 4-to-1 mux with
    // _a_ and _b_ as the selector inputs.  The truth table for the
    // circuit is:
    //
    //      a  b  mux_in
    //      0  0      0
    //      0  1      0
    //      1  0      0
