  parameter C = 2'b10;
  parameter D = 2'b11;
  reg [1:0] state, next_state;
  // State transition logic
  always @(*) begin
    casez ({
      in, state
    })
      {1'b0, A} : next_state = A;
      {1'b1, A} : next_state = B;
      {1'b0, B} : next_state = C;
      {1'b1, B} : next_state = B;
      {1'b0, C} : next_state = A;
      {1'b1, C} : next_state = D;
      {1'b0, D} : next_state = C;
      {1'b1, D} : next_state = B;
      default: next_state = A;
    endcase
  end
  // State flip-flops with asynchronous reset
  always @(posedge clk, posedge areset) begin
    if (areset) state <= A;
    else if (clk) state <= next_state;
  end
  // Output logic
  assign out = (state == D);
endmodule

