  reg [1:0] state, next_state;
  // sequential logic
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end
  // combinational logic
  always @(*) begin
    case (state)
      A: next_state = in ? B : A;
      B: next_state = in ? C : B;
      C: next_state = in ? D : A;
      D: next_state = in ? C : B;
    endcase
  end
  // combinational logic output
  assign out = (state == D) ? 1'b1 : 1'b0;
endmodule

