                       START = 2'b01,
                       DATA  = 2'b10,
                       STOP  = 2'b11 ;
    reg [ 1:0 ] state, next_state ;
    reg [ 3:0 ] count ;
    always @ ( posedge clk )
        if ( reset )
            state <= IDLE ;
        else
            state <= next_state ;
    always @ ( posedge clk )
        if ( reset )
            count <= 4'h0 ;
        else
            case ( state )
                IDLE  : count <= 4'h0 ;
                START : count <= 4'h0 ;
                DATA  : count <= count + 4'h1 ;
                STOP  : count <= 4'h0 ;
            endcase
    always @ *
        case ( state )
            IDLE  : next_state = in ? IDLE : START ;
            START : next_state = DATA ;
            DATA  : next_state = count == 4'h8 ? STOP : DATA ;
            STOP  : next_state = in ? IDLE : START ;
        endcase
    assign done = state == STOP ;
endmodule

