    reg [7:0] hh_internal, mm_internal, ss_internal;
    reg pm_internal;
    always @ ( posedge clk ) begin
        if (reset) begin
            hh_internal <= 8'h12;
            mm_internal <= 8'h00;
            ss_internal <= 8'h00;
            pm_internal <= 1'b0;
        end
        else if (ena) begin
            if (ss_internal == 8'h59) begin
                ss_internal <= 8'h00;
                if (mm_internal == 8'h59) begin
                    mm_internal <= 8'h00;
                    if (hh_internal == 8'h11) begin
                        hh_internal <= 8'h12;
                        pm_internal <= ~pm_internal;
                    end
                    else if (hh_internal[3:0] == 4'h9) begin
                        hh_internal <= {hh_internal[7:4] + 4'h1, 4'h0};
                    end
                    else begin
                        hh_internal <= {hh_internal[7:4], hh_internal[3:0] + 4'h1};
                    end
                end
                else begin
                    mm_internal <= {mm_internal[7:4] + 4'h1, mm_internal[3:0] + 4'h1};
                end
            end
            else begin
                ss_internal <= {ss_internal[7:4] + 4'h1, ss_internal[3:0] + 4'h1};
            end
        end
    end
    assign pm = pm_internal;
    assign hh = hh_internal;
    assign mm = mm_internal;
    assign ss = ss_internal;
