    output walk_right,
    output aaah
) ;
    parameter LEFT = 0, RIGHT = 1, FALL_L = 2, FALL_R = 3;
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            LEFT  : next_state = (ground == 0) ? FALL_L : (bump_left == 1) ? RIGHT : LEFT;
            RIGHT : next_state = (ground == 0) ? FALL_R : (bump_right == 1) ? LEFT : RIGHT;
            FALL_L: next_state = (ground == 1) ? LEFT   : FALL_L;
            FALL_R: next_state = (ground == 1) ? RIGHT  : FALL_R;
        endcase
    end
    always @(posedge clk, posedge areset) begin
        if (areset == 1) begin
            state <= LEFT;
        end else begin
            state <= next_state;
        end
    end
    assign walk_left = (state == LEFT) ? 1 : 0;
    assign walk_right = (state == RIGHT) ? 1 : 0;
    assign aaah = (state == FALL_L || state == FALL_R) ? 1 : 0;
endmodule

