              B = 3'b001,
              C = 3'b010,
              D = 3'b011;
    reg [2:0] cstate, nstate;
    // state table
    always @(*) begin
        case (cstate)
            A:  nstate = (_r[0] == 1'b0) ? A : B;
            B:  nstate = (_r[0] == 1'b1) ? B : A;
            C:  nstate = (_r[1] == 1'b1) ? C : A;
            D:  nstate = (_r[2] == 1'b1) ? D : A;
            default: nstate = A;
        endcase
    end
    // state FF
    always @(posedge clk) begin
        if (resetn == 1'b0)
            cstate <= A;
        else
            cstate <= nstate;
    end
    // output logic
    // assign _g[i] = (cstate == ...);
    // or
    assign _g[0] = (cstate == B);
    assign _g[1] = (cstate == C);
    assign _g[2] = (cstate == D);
    assign state = cstate;
endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
) ;
    reg [2:0] state, next_state;
    reg [1:0] fr;
    reg dfr_r;
    always @(posedge clk) begin
        if (reset)
            state <= 0;
        else
            state <= next_state;
    end
    always @(*) begin
        case (state)
            0: begin
                next_state = s[0] ? 1 : (s[1] ? 2 : (s[2] ? 3 : 0));
                dfr_r = 0;
            end
            1: begin
                next_state = s[0] ? 1 : 0;
                dfr_r = 0;
            end
            2: begin
                next_state = s[1] ? 2 : (s[0] ? 1 : 0);
                dfr_r = 0;
            end
            3: begin
                next_state = s[2] ? 3 : (s[1] ? 2 : (s[0] ? 1 : 0));
                dfr_r = !s[2] && s[1];
            end
        endcase
    end
    always @(*) begin
        case (state)
            0: fr = 2'b11;
            1: fr = 2'b10;
            2: fr = 2'b01;
            3: fr = 2'b00;
        endcase
    end
    assign {fr2, fr1, fr0} = fr;
    assign dfr = dfr_r;
endmodule

module TopModule (
    input  d,
