    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
) ;
    // Derive next-state logic equations and output logic equations by
    // inspection. See text above.
    //
    // State transition logic (combinational) -- output logic
    assign B3_next     = state[8] & state[0];
    assign S_next      = state[0] & ~d | state[1] & ~d | state[3] & ~d | state[4] & ~d | state[7] & ~d | state[9] & ~d;
    assign S1_next     = state[0] & d | state[1] & d | state[3] & d | state[4] & d;
    assign Count_next  = state[5] & done_counting | state[6] & done_counting;
    assign Wait_next   = state[5] & ~done_counting | state[6] & ~done_counting | state[7] & ~ack;
    // Output logic
    assign done        = state[7] & ack;
    assign counting    = state[5];
    assign shift_ena   = state[6] | state[7] | state[8] | state[9];
endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
) ;
    // FSM from fsm_ps2
    parameter SEARCH = 0, FOUND_1 = 1, FOUND_11 = 2, FOUND_110 = 3, FOUND_1101 = 4, WAIT_COUNT = 5, NOTIFY = 6;
    reg [2:0] state, next_state;
    reg shift_ena_reg, counting_reg, done_reg;
    always @(posedge clk) begin
        if (reset) begin
            state <= SEARCH;
        end else begin
            state <= next_state;
        end
    end
    always @(*) begin
        next_state = state;
        shift_ena_reg = 1'b0;
        counting_reg = 1'b0;
        done_reg = 1'b0;
        case (state)
            SEARCH: begin
                if (data == 1'b1) begin
                    next_state = FOUND_1;
                end
            end
            FOUND_1: begin
                if (data == 1'b1) begin
                    next_state = FOUND_11;
                end else begin
                    next_state = SEARCH;
                end
            end
            FOUND_11: begin
                if (data == 1'b0) begin
                    next_state = FOUND_110;
                end
            end
            FOUND_110: begin
                if (data == 1'b1) begin
                    next_state = FOUND_1101;
                end else begin
                    next_state = SEARCH;
                end
            end
            FOUND_1101: begin
                shift_ena_reg = 1'b1;
                next_state = WAIT_COUNT;
            end
            WAIT_COUNT: begin
                counting_reg = 1'b1;
                if (done_counting) begin
                    next_state = NOTIFY;
                end
            end
            NOTIFY: begin
                done_reg = 1'b1;
                if (ack == 1'b1) begin
                    next_state = SEARCH;
