module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
) ;
    parameter LEFT = 0, RIGHT = 1, FALL_LEFT = 2, FALL_RIGHT = 3, DIG_LEFT = 4, DIG_RIGHT = 5, SPLATTER = 6;
    parameter TIMEOUT = 20;
    reg [2:0] state, next_state;
    reg [4:0] counter;
    always @(posedge clk, posedge areset) begin
        if (areset) begin
            state <= LEFT;
            counter <= 0;
        end
        else begin
            state <= next_state;
            if (state == FALL_LEFT || state == FALL_RIGHT)
                counter <= counter + 1;
            else
                counter <= 0;
        end
    end
    always @(*) begin
        case (state)
            LEFT: begin
                if (ground) begin
                    if (dig)
                        next_state = DIG_LEFT;
                    else if (bump_left)
                        next_state = RIGHT;
                    else
                        next_state = LEFT;
                end
                else
                    next_state = FALL_LEFT;
            end
            RIGHT: begin
                if (ground) begin
                    if (dig)
                        next_state = DIG_RIGHT;
                    else if (bump_right)
                        next_state = LEFT;
                    else
                        next_state = RIGHT;
                end
                else
                    next_state = FALL_RIGHT;
            end
            FALL_LEFT: begin
                if (ground) begin
                    if (counter > TIMEOUT)
                        next_state = SPLATTER;
                    else
                        next_state = LEFT;
                end
                else
                    next_state = FALL_LEFT;
            end
            FALL_RIGHT: begin
                if (ground) begin
                    if (counter > TIMEOUT)
                        next_state = SPLATTER;
                    else
                        next_state = RIGHT;
                end
                else
                    next_state = FALL_RIGHT;
            end
            DIG_LEFT: begin
                if (ground)
                    next_state = DIG_LEFT;
                else
                    next_state = FALL_LEFT;
            end
            DIG_RIGHT: begin
                if (ground)
                    next_state = DIG_RIGHT;
                else
                    next_state = FALL_RIGHT;
            end
            SPLATTER: next_state = SPLATTER;
        endcase
    end
    assign walk_left = (state == LEFT);
    assign walk_right = (state == RIGHT);
    assign aaah = (state == FALL_LEFT || state == FALL_RIGHT);
    assign digging = (state == DIG_LEFT || state == DIG_RIGHT);
endmodule

