module TopModule (
  input clk,
  input in,
  input reset,
  output [7:0] out_byte,
  output done
);
  parameter IDLE = 0, START = 1, DATA = 2, STOP = 3;
  reg [1:0] state, next_state;
  reg [3:0] data_count;
  reg [7:0] data;
  always @(*) begin
    case (state)
      IDLE: next_state = in ? IDLE : START;
      START: next_state = DATA;
      DATA: next_state = (data_count < 8) ? DATA : (in ? STOP : IDLE);
      STOP: next_state = in ? IDLE : START;
      default: next_state = IDLE;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      data_count <= 0;
    end else begin
      state <= next_state;
      if (state == DATA) begin
        data_count <= data_count + 1;
        data[data_count] <= in;
      end else begin
        data_count <= 0;
      end
    end
  end
  assign done = (state == STOP);
  assign out_byte = (state == STOP) ? data : 8'b0;
endmodule

