module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);
  reg [2:0] state, next_state;
  always @(*) begin
    case (state)
      3'd0: next_state = (data == 1'b1 ? 3'd1 : 3'd0);
      3'd1: next_state = (data == 1'b1 ? 3'd2 : 3'd0);
      3'd2: next_state = (data == 1'b1 ? 3'd3 : 3'd0);
      3'd3: next_state = (data == 1'b1 ? 3'd3 : 3'd4);
      3'd4: next_state = (done_counting == 1'b1 ? 3'd5 : 3'd4);
      3'd5: next_state = (ack == 1'b1 ? 3'd0 : 3'd5);
      default: next_state = 3'd0;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'd0;
    end else begin
      state <= next_state;
    end
  end
  always @(*) begin
    shift_ena = 1'b0;
    counting = 1'b0;
    done = 1'b0;
    case (state)
      3'd4: shift_ena = 1'b1;
      3'd5: counting = 1'b1;
      default: done = 1'b0;
    endcase
  end
endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);
  parameter LEFT = 0, RIGHT = 1, FALL_LEFT = 2, FALL_RIGHT = 3, DIG_LEFT = 4, DIG_RIGHT = 5;
  reg [2:0] state, next_state;
  always @(*) begin
    case (state)
      LEFT: next_state = ground ? (dig ? DIG_LEFT : (bump_left ? RIGHT : LEFT)) : FALL_LEFT;
      RIGHT: next_state = ground ? (dig ? DIG_RIGHT : (bump_right ? LEFT : RIGHT)) : FALL_RIGHT;
      FALL_LEFT: next_state = ground ? LEFT : FALL_LEFT;
      FALL_RIGHT: next_state = ground ? RIGHT : FALL_RIGHT;
      DIG_LEFT: next_state = ground ? DIG_LEFT : FALL_LEFT;
      DIG_RIGHT: next_state = ground ? DIG_RIGHT : FALL_RIGHT;
      default: next_state = LEFT;
    endcase
  end
  always @(posedge clk, posedge areset) begin
    if (areset) begin
      state <= LEFT;
    end else begin
      state <= next_state;
    end
  end
  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);
  assign aaah = (state == FALL_LEFT) || (state == FALL_RIGHT);
  assign digging = (state == DIG_LEFT) || (state == DIG_RIGHT);
endmodule

module TopModule (
  input clk,
  input areset,
  input predict_valid,
  input [6:0] predict_pc,
  output predict_taken,
  output [6:0] predict_history,
  input train_valid,
  input train_taken,
  input train_mispredicted,
  input [6:0] train_history,
  input [6:0] train_pc
);
  reg [1:0] pht[127:0];
  reg [6:0] ghb;
  wire [6:0] index;
  wire [6:0] ghr_update;
  wire [1:0] update_signal;
  wire update;
  assign index = predict_pc ^ ghb;
  assign predict_taken = pht[index][1];
  assign predict_history = ghb;
  assign ghr_update = train_valid ? train_history : predict_valid ? predict_pc ^ ghb : 0;
  assign update_signal = {train_valid & train_mispredicted, train_valid & ~train_mispredicted};
  assign update = |update_signal;
  integer i;
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      for (i = 0; i < 128; i = i + 1) begin
        pht[i] <= 2'b01;
      end
      ghb <= 0;
    end else begin
      if (update) begin
        if (train_valid) begin
          pht[train_pc ^ ghb] <= pht[train_pc ^ ghb] + update_signal[1] - update_signal[0];
        end
        if (predict_valid) begin
          ghb <= ghb ^ ghr_update;
        end
      end
    end
  end
endmodule

