          end else begin
            state <= STATE_BYTE1;
            byte1 <= in;
            byte2 <= 8'b0;
            byte3 <= 8'b0;
            out_bytes <= 24'b0;
          end
        end
        STATE_BYTE2: begin
          if (in[3] == 1'b1) begin
            state <= STATE_BYTE3;
            byte1 <= byte1;
            byte2 <= in;
            byte3 <= 8'b0;
            out_bytes <= 24'b0;
          end else begin
            state <= STATE_BYTE2;
            byte1 <= byte1;
            byte2 <= in;
            byte3 <= 8'b0;
            out_bytes <= 24'b0;
          end
        end
        STATE_BYTE3: begin
          if (in[3] == 1'b1) begin
            state <= STATE_BYTE1;
            byte1 <= in;
            byte2 <= 8'b0;
            byte3 <= 8'b0;
            out_bytes <= {byte1, byte2, in};
          end else begin
            state <= STATE_BYTE3;
            byte1 <= byte1;
            byte2 <= byte2;
            byte3 <= in;
            out_bytes <= {byte1, byte2, byte3};
          end
        end
      endcase
    end
  end
  assign done = (state == STATE_BYTE3 && in[3] == 1'b1);
endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);
  parameter LEFT = 0, RIGHT = 1;
  reg state, next_state;
  reg [4:0] counter;
  always @(*) begin
    case (state)
      LEFT: next_state = (ground == 1'b0) ? LEFT : (dig == 1'b1) ? LEFT : (bump_left == 1'b1) ? RIGHT : LEFT;
      RIGHT: next_state = (ground == 1'b0) ? RIGHT : (dig == 1'b1) ? RIGHT : (bump_right == 1'b1) ? LEFT : RIGHT;
    endcase
  end
  always @(posedge clk, posedge areset) begin
    if (areset) begin
      state <= LEFT;
      counter <= 5'd0;
    end else begin
      if (state != next_state) begin
        counter <= 5'd0;
      end else if (ground == 1'b0) begin
        counter <= counter + 5'd1;
      end
      state <= next_state;
    end
  end
  assign walk_left = (state == LEFT) ? 1'b1 : 1'b0;
  assign walk_right = (state == RIGHT) ? 1'b1 : 1'b0;
  assign aaah = (ground == 1'b0) ? 1'b1 : 1'b0;
  assign digging = (state == LEFT || state == RIGHT) ? (ground == 1'b1 && counter <= 5'd20) ? 1'b1 : 1'b0 : 1'b0;
endmodule

module TopModule (
  input wire clk,
  input wire reset,
  input wire data,
  output wire [3:0] count,
  output reg counting,
  output reg done,
  input wire ack
);
  reg [3:0] delay;
  reg [3:0] counter;
  reg [3:0] state;
  reg [3:0] next_state;
  reg [3:0] shift_reg;
  reg [3:0] shift_reg_next;
  reg [3:0] counter_next;
  reg [3:0] delay_next;
  reg counting_next;
  reg done_next;
  always @(posedge clk) begin
    if (reset) begin
      state <= 4'b0000;
      shift_reg <= 4'b0000;
      counter <= 4'b0000;
      delay <= 4'b0000;
      counting <= 1'b0;
      done <= 1'b0;
    end else begin
      state <= next_state;
      shift_reg <= shift_reg_next;
      counter <= counter_next;
      delay <= delay_next;
      counting <= counting_next;
      done <= done_next;
    end
  end
  always @(*) begin
    next_state = state;
    shift_reg_next = shift_reg;
    counter_next = counter;
    delay_next = delay;
    counting_next = counting;
    done_next = done;
    case (state)
      4'b0000: begin
        if (shift_reg == 4'b1101) begin
          next_state = 4'b0001;
          shift_reg_next = 4'b0000;
        end else begin
          next_state = 4'b0000;
          shift_reg_next = {shift_reg[2:0], data};
        end
      end
      4'b0001: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0010;
          shift_reg_next = 4'b0000;
          counter_next = delay;
        end else begin
          next_state = 4'b0010;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0010: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0011;
          shift_reg_next = 4'b0000;
          counter_next = delay - 1'b1;
        end else begin
          next_state = 4'b0010;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0011: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0100;
          shift_reg_next = 4'b0000;
          counter_next = delay - 2'b10;
        end else begin
          next_state = 4'b0011;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0100: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0101;
          shift_reg_next = 4'b0000;
          counter_next = delay - 3'b100;
        end else begin
          next_state = 4'b0100;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0101: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0110;
          shift_reg_next = 4'b0000;
          counter_next = delay - 4'b1000;
        end else begin
          next_state = 4'b0101;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0110: begin
        if (counter == 4'b0000) begin
          next_state = 4'b0111;
          shift_reg_next = 4'b0000;
          counter_next = 4'b0000;
        end else begin
          next_state = 4'b0110;
          shift_reg_next = shift_reg;
          counter_next = counter - 1'b1;
        end
      end
      4'b0111: begin
        if (ack == 1'b1) begin
          next_state = 4'b0000;
          shift_reg_next = 4'b0000;
          counter_next = 4'b0000;
        end else begin
          next_state = 4'b0111;
          shift_reg_next = shift_reg;
          counter_next = counter;
        end
      end
    endcase
  end
  assign count = delay;
  always @(*) begin
    if (state == 4'b0001 || state == 4'b0010 || state == 4'b0011 || state == 4'b0100 || state == 4'b0101 || state == 4'b0110) begin
      counting_next = 1'b1;
    end else begin
      counting_next = 1'b0;
    end
  end
  always @(*) begin
    if (state == 4'b0111) begin
      done_next = 1'b1;
    end else begin
      done_next = 1'b0;
    end
  end
endmodule
